    def compute_nonlocal_term(self, n: int, t: float) -> Tuple[float, str]:
        """
        Compute non-local interaction term from Red Dwarf Reactor data
        
        [SSq]^n26 × exp(-π - t)
        
        Parameters:
            n: Quantum state number (1-26)
            t: Time (s)
            
        Returns:
            Non-local term value and calculation steps
        """
        SSq = CONSTANTS['SSq_base']  # 0.57
        
        # [SSq]^(n/26) × exp(-π - t)
        SSq_power = SSq ** (n / 26)
        exp_term = np.exp(-np.pi - t)
        nl_val = SSq_power * exp_term
        
        steps = f"""
    Non-Local Interaction Term
    ═══════════════════════════════════════════════════════════════
    
    EQUATION: [SSq]^(n/26) × exp(-π - t)
    
    Step 1: Parameters
            [SSq] = {SSq} (calibrated value)
            n = {n} (quantum state)
            t = {t:.4e} s
    
    Step 2: Power term
            [SSq]^(n/26) = {SSq}^({n}/26) = {SSq_power:.6e}
    
    Step 3: Exponential term
            exp(-π - t) = exp({-np.pi - t:.6f}) = {exp_term:.6e}
    
    Step 4: Non-local term
            [SSq]^(n/26) × exp(-π - t) = {SSq_power:.6e} × {exp_term:.6e}
            = {nl_val:.6e}
    
    PHYSICAL MEANING:
        This term models non-local jumps observed in plasmoid behavior
        in Red Dwarf Reactor experiments. Decays rapidly with time."""
        
        return nl_val, steps
    
    def compute_negative_time_operator(self, t_n: float) -> Tuple[float, str]:
        """
        Compute negative time operator for quantum state transitions
        
        t⁻ = -t_n × exp(π - t_n)
        
        Parameters:
            t_n: Normalized time relative to reference
            
        Returns:
            Negative time operator value and steps
        """
        t_minus = -t_n * np.exp(np.pi - t_n)
        
        steps = f"""
    Negative Time Operator
    ═══════════════════════════════════════════════════════════════
    
    EQUATION: t⁻ = -t_n × exp(π - t_n)
    
    Step 1: Input
            t_n = {t_n:.4f} (normalized time)
    
    Step 2: Exponent
            π - t_n = {np.pi - t_n:.4f}
            exp(π - t_n) = {np.exp(np.pi - t_n):.4e}
    
    Step 3: Negative time
            t⁻ = -{t_n:.4f} × {np.exp(np.pi - t_n):.4e}
            t⁻ = {t_minus:.4e}
    
    PHYSICAL MEANING:
        Drives transitions between 26 quantum states.
        Enables time-reversal effects in TRZs.
        Note: t⁻ is negative, indicating backward time flow."""
        
        return t_minus, steps
    
    def compute_quark_mass_energy(self, quark: str, n: int = None) -> Tuple[float, str]:
        """
        Compute UQFF-modified quark mass energy with quantum state
        
        E_q = m_q × c² × exp(n/26)
        
        Parameters:
            quark: 'u', 'd', 'c', 's', 't', or 'b'
            n: Quantum state (1-26), default uses particle's assigned state
            
        Returns:
            Mass energy in J and calculation steps
        """
        if quark not in self.quarks:
            raise ValueError(f"Unknown quark: {quark}")
        
        q = self.quarks[quark]
        c = CONSTANTS['c']
        m_q = q['mass_kg']
        if n is None:
            n = q['quantum_state']
        
        # E_q = m_q × c² × exp(n/26)
        E_base = m_q * c**2
        quantum_factor = np.exp(n / 26)
        E_q = E_base * quantum_factor
        
        steps = f"""
    Quark Mass Energy ({q['name']} Quark, n={n})
    ═══════════════════════════════════════════════════════════════
    
    EQUATION: E_q = m_q × c² × exp(n/26)
    
    Step 1: Quark parameters
            Quark: {q['symbol']} ({q['name']})
            Mass: m_q = {m_q:.4e} kg
            Charge: q = {q['charge']:.2f}e
            Generation: {q['generation']}
    
    Step 2: Base mass energy
            E_base = m_q × c²
            E_base = {m_q:.4e} × ({c:.4e})²
            E_base = {E_base:.4e} J
            E_base = {E_base / 1.602e-19 / 1e6:.3f} MeV
    
    Step 3: Quantum state factor
            exp(n/26) = exp({n}/26) = exp({n/26:.4f})
            = {quantum_factor:.6f}
    
    Step 4: UQFF mass energy
            E_q = {E_base:.4e} × {quantum_factor:.6f}
            E_q = {E_q:.4e} J
            E_q = {E_q / 1.602e-19 / 1e6:.3f} MeV
    
    UQFF INTERPRETATION:
        The factor exp(n/26) modifies mass based on quantum state.
        Higher states (n→26) have enhanced effective mass.
        This bridges physical and conscious reality dimensions."""
        
        return E_q, steps
    
    def compute_quark_energy_density(self, quark: str, t: float = 0, 
                                      t_n: float = 0) -> Tuple[float, str]:
        """
        Compute quark energy density in UQFF framework
        
        U_q = λ_q × ρ_vac,[SCm] × ρ_vac,[UA] × ω_q(t) × cos(πt_n) × (1+f_TRZ) 
              × exp(-[SSq]^n26 × exp(-π-t))
        
        Parameters:
            quark: 'u', 'd', 'c', 's', 't', or 'b'
            t: Time (s)
            t_n: Normalized time
            
        Returns:
            Energy density in J/m³ and calculation steps
        """
        if quark not in self.quarks:
            raise ValueError(f"Unknown quark: {quark}")
        
        q = self.quarks[quark]
        
        # Get parameters
        lambda_q = q['lambda']
        omega_q = q['omega']
        n = q['quantum_state']
        rho_SCm = CONSTANTS['rho_vac_SCm']  # 7.09e-37 at solar scale
        rho_UA = CONSTANTS['rho_vac_UA']    # 7.09e-36 at solar scale
        f_TRZ = CONSTANTS['f_TRZ']          # 0.1
        
        # Compute terms
        cos_term = np.cos(np.pi * t_n)
        nl_val, _ = self.compute_nonlocal_term(n, t)
        
        # U_q = λ_q × ρ_SCm × ρ_UA × ω_q × cos(πt_n) × (1+f_TRZ) × exp(-nl_val)
        U_q = lambda_q * rho_SCm * rho_UA * omega_q * cos_term * (1 + f_TRZ) * np.exp(-nl_val)
        
        steps = f"""
    Quark Energy Density in Aether ({q['name']} Quark)
    ═══════════════════════════════════════════════════════════════════════════════
    
    EQUATION:
        U_q = λ_q × ρ_vac,[SCm] × ρ_vac,[UA] × ω_q(t) × cos(πt_n) × (1+f_TRZ)
              × exp(-[SSq]^(n/26) × exp(-π-t))
    
    ───────────────────────────────────────────────────────────────────────────────
    PARAMETERS
    ───────────────────────────────────────────────────────────────────────────────
        Quark: {q['symbol']} ({q['name']})
        λ_q (coupling) = {lambda_q}
        ω_q (vortex freq) = {omega_q:.2e} rad/s
        n (quantum state) = {n}
        t = {t:.4e} s
        t_n = {t_n:.4f}
    
    ───────────────────────────────────────────────────────────────────────────────
    VACUUM DENSITIES
    ───────────────────────────────────────────────────────────────────────────────
        ρ_vac,[SCm] = {rho_SCm:.4e} J/m³
        ρ_vac,[UA] = {rho_UA:.4e} J/m³
    
    ───────────────────────────────────────────────────────────────────────────────
    CALCULATION
    ───────────────────────────────────────────────────────────────────────────────
        cos(πt_n) = cos({np.pi * t_n:.4f}) = {cos_term:.6f}
        f_TRZ = {f_TRZ}
        (1 + f_TRZ) = {1 + f_TRZ}
        Non-local term = {nl_val:.6e}
        exp(-nl_val) = {np.exp(-nl_val):.6f}
    
        U_q = {lambda_q} × {rho_SCm:.4e} × {rho_UA:.4e} × {omega_q:.2e}
              × {cos_term:.6f} × {1 + f_TRZ} × {np.exp(-nl_val):.6f}
        U_q = {U_q:.4e} J/m³
    
    PHYSICAL INTERPRETATION:
        Quarks are quantized vortices in the [UA] superfluid.
        Energy density depends on coupling to [SCm] + [UA] vacuum.
        Non-local term reflects quark confinement via gluon exchange."""
        
        return U_q, steps
    
    def compute_gluon_energy_density(self, t: float = 0, n: int = 14) -> Tuple[float, str]:
        """
        Compute gluon energy density in UQFF
        
        U_g = λ_g × ρ_vac,[UA] × ω_g(t) × exp(-[SSq]^n26 × exp(-π-t)) × (1+f_quasi)
        
        Parameters:
            t: Time (s)
            n: Quantum state (default 14 for gluons)
            
        Returns:
            Energy density in J/m³ and calculation steps
        """
        lambda_g = CONSTANTS['lambda_g']
        omega_g = CONSTANTS['omega_g']
        rho_UA = CONSTANTS['rho_vac_UA']
        f_quasi = CONSTANTS['f_quasi']
        
        nl_val, _ = self.compute_nonlocal_term(n, t)
        
        U_g = lambda_g * rho_UA * omega_g * np.exp(-nl_val) * (1 + f_quasi)
        
        # Color charge interaction: E_color = g_s × ρ_UA / r
        g_s = CONSTANTS['g_s']
        
        steps = f"""
    Gluon Energy Density in Aether
    ═══════════════════════════════════════════════════════════════════════════════
    
    EQUATION:
        U_g = λ_g × ρ_vac,[UA] × ω_g(t) × exp(-[SSq]^(n/26) × exp(-π-t)) × (1+f_quasi)
    
    PARAMETERS:
        λ_g = {lambda_g} (gluon coupling)
        ω_g = {omega_g:.2e} rad/s (exchange frequency)
        ρ_vac,[UA] = {rho_UA:.4e} J/m³
        f_quasi = {f_quasi} (quasi-longitudinal wave factor)
        n = {n} (quantum state)
        t = {t:.4e} s
    
    CALCULATION:
        Non-local term = {nl_val:.6e}
        exp(-nl_val) = {np.exp(-nl_val):.6f}
        
        U_g = {lambda_g} × {rho_UA:.4e} × {omega_g:.2e} 
              × {np.exp(-nl_val):.6f} × (1 + {f_quasi})
        U_g = {U_g:.4e} J/m³
    
    COLOR CHARGE INTERACTION:
        E_color = g_s × ρ_vac,[UA] / r
        g_s = {g_s} (strong coupling constant)
        α_s at M_Z = {CONSTANTS['alpha_s_MZ']} (running coupling)
        N_gluon_colors = {CONSTANTS['N_gluon_colors']} (8 combinations)
    
    PHYSICAL INTERPRETATION:
        Gluons are non-local energy fluctuations in [UA].
        Mediate strong force between quarks via color charge.
        Jump probability: P_jump = [SSq]^(n/26) × exp(-π-t)"""
        
        return U_g, steps
    
    def compute_lepton_energy_density(self, lepton: str, t: float = 0, 
                                       t_n: float = 0) -> Tuple[float, str]:
        """
        Compute lepton energy density in UQFF
        
        U_l = λ_l × ρ_vac,[SCm] × ρ_vac,[UA] × ω_l(t) × cos(πt_n) × (1+f_TRZ)
              × exp(-[SSq]^n26 × exp(-π-t))
        
        Parameters:
            lepton: 'e', 'mu', 'tau', 'nu_e', 'nu_mu', or 'nu_tau'
            t: Time (s)
            t_n: Normalized time
            
        Returns:
            Energy density in J/m³ and calculation steps
        """
        if lepton not in self.leptons:
            raise ValueError(f"Unknown lepton: {lepton}")
        
        l = self.leptons[lepton]
        
        # Get parameters
        lambda_l = l.get('lambda', 1.0)  # Default 1.0 if not specified
        omega_l = l.get('omega', 1e18)   # Default for neutrinos
        n = l['quantum_state']
        rho_SCm = CONSTANTS['rho_vac_SCm']
        rho_UA = CONSTANTS['rho_vac_UA']
        f_TRZ = CONSTANTS['f_TRZ']
        
        # Compute terms
        cos_term = np.cos(np.pi * t_n)
        nl_val, _ = self.compute_nonlocal_term(n, t)
        
        U_l = lambda_l * rho_SCm * rho_UA * omega_l * cos_term * (1 + f_TRZ) * np.exp(-nl_val)
        
        steps = f"""
    Lepton Energy Density ({l['name']})
    ═══════════════════════════════════════════════════════════════════════════════
    
    EQUATION:
        U_l = λ_l × ρ_vac,[SCm] × ρ_vac,[UA] × ω_l(t) × cos(πt_n) × (1+f_TRZ)
              × exp(-[SSq]^(n/26) × exp(-π-t))
    
    LEPTON: {l['symbol']} ({l['name']})
        Mass: {l['mass_eV']:.3e} eV/c²
        Charge: {l['charge']}e
        Spin: {l['spin']}
        Generation: {l['generation']}
        Quantum state: n = {n}
    
    PARAMETERS:
        λ_l = {lambda_l}
        ω_l = {omega_l:.2e} rad/s
        ρ_vac,[SCm] = {rho_SCm:.4e} J/m³
        ρ_vac,[UA] = {rho_UA:.4e} J/m³
        f_TRZ = {f_TRZ}
        t = {t:.4e} s, t_n = {t_n:.4f}
    
    CALCULATION:
        cos(πt_n) = {cos_term:.6f}
        Non-local term = {nl_val:.6e}
        exp(-nl_val) = {np.exp(-nl_val):.6f}
        
        U_l = {U_l:.4e} J/m³
    
    NEUTRINO OSCILLATION (if applicable):
        P(ν_e → ν_μ) = sin²(2θ) × sin²(Δm²L / 4E_ν)
        θ₁₂ = {CONSTANTS['theta_12']:.4f} rad (solar)
        θ₂₃ = {CONSTANTS['theta_23']:.4f} rad (atmospheric)
        θ₁₃ = {CONSTANTS['theta_13']:.4f} rad (reactor)
    
    PHYSICAL INTERPRETATION:
        Leptons are toroidal vortices in [UA] superfluid.
        Electrons have dual [SCm]/[SCm'] nature."""
        
        return U_l, steps
    
    def compute_pondermotive_force(self, particle: str, E_field: float, 
                                    omega: float = None) -> Tuple[float, str]:
        """
        Compute pondermotive force in Time-Reversal Zones (TRZs)
        
        F_p = -(q²/4mω²) × ∇(E²)
        
        For a uniform gradient approximation: F_p = -(q²/4mω²) × (E²/L)
        
        Parameters:
            particle: Quark or lepton name
            E_field: Electric field magnitude (V/m)
            omega: Angular frequency (rad/s), or uses particle default
            
        Returns:
            Pondermotive force magnitude and calculation steps
        """
        # Get particle mass and charge
        if particle in self.quarks:
            p = self.quarks[particle]
            m = p['mass_kg']
            q = p['charge'] * 1.602e-19  # Convert to C
            omega = omega or p['omega']
        elif particle in self.leptons:
            p = self.leptons[particle]
            m = p.get('mass_kg', p['mass_eV'] * 1.602e-19 / (CONSTANTS['c']**2))
            q = p['charge'] * 1.602e-19
            omega = omega or p.get('omega', 1e18)
        else:
            raise ValueError(f"Unknown particle: {particle}")
        
        # F_p magnitude (assuming gradient scale L = 1e-15 m for subatomic)
        L = 1e-15  # Gradient length scale (fm)
        
        F_p = abs(q**2 / (4 * m * omega**2) * E_field**2 / L)
        
        steps = f"""
    Pondermotive Force in TRZ ({p['name']})
    ═══════════════════════════════════════════════════════════════════════════════
    
    EQUATION: F_p = -(q²/4mω²) × ∇(E²)
    
    From Ideal Gravity document: Oscillating fields in TRZs contribute
    to negentropic effects (local entropy decrease).
    
    PARTICLE: {p.get('symbol', particle)}
        Mass: m = {m:.4e} kg
        Charge: q = {q:.4e} C
        Frequency: ω = {omega:.4e} rad/s
    
    FIELD PARAMETERS:
        E = {E_field:.4e} V/m
        L (gradient scale) = {L:.4e} m (subatomic scale)
    
    CALCULATION:
        q² = {q**2:.4e} C²
        4mω² = 4 × {m:.4e} × ({omega:.4e})²
             = {4 * m * omega**2:.4e}
        
        E²/L = ({E_field:.4e})² / {L:.4e}
             = {E_field**2 / L:.4e} V²/m³
        
        F_p = {q**2:.4e} / {4 * m * omega**2:.4e} × {E_field**2 / L:.4e}
        F_p = {F_p:.4e} N
    
    NEGENTROPIC EFFECT:
        In TRZs, this force can drive particles against entropy gradient,
        enabling COP > 1 energy extraction (Red Dwarf Reactor)."""
        
        return F_p, steps
    
    def compute_meson_energy_density(self, meson: str, t: float = 0, 
                                      t_n: float = 0) -> Tuple[float, str]:
        """
        Compute meson (quark-antiquark) energy density in UQFF
        
        U_K = λ_K × ρ_vac,[SCm] × ρ_vac,[UA] × ω_K(t) × cos(πt_n) × (1+f_TRZ)
        
        Parameters:
            meson: 'K_plus', 'K_zero', 'pi_plus', 'pi_zero'
            t: Time (s)
            t_n: Normalized time
            
        Returns:
            Energy density and calculation steps
        """
        if meson not in self.mesons:
            raise ValueError(f"Unknown meson: {meson}")
        
        m = self.mesons[meson]
        
        lambda_m = 1.0
        omega_m = 1e20  # Approximate meson vortex frequency
        n = m['quantum_state']
        rho_SCm = CONSTANTS['rho_vac_SCm']
        rho_UA = CONSTANTS['rho_vac_UA']
        f_TRZ = CONSTANTS['f_TRZ']
        
        cos_term = np.cos(np.pi * t_n)
        
        U_m = lambda_m * rho_SCm * rho_UA * omega_m * cos_term * (1 + f_TRZ)
        
        # Decay rate: Γ = 1/τ
        tau = m.get('lifetime', m.get('lifetime_S', 1e-8))
        Gamma = 1 / tau
        
        steps = f"""
    Meson Energy Density ({m['name']})
    ═══════════════════════════════════════════════════════════════════════════════
    
    EQUATION:
        U_K = λ × ρ_vac,[SCm] × ρ_vac,[UA] × ω(t) × cos(πt_n) × (1+f_TRZ)
    
    MESON: {m['symbol']} ({m['name']})
        Quark content: {m['quark_content']}
        Mass: {m['mass_eV'] / 1e6:.3f} MeV/c²
        Charge: {m['charge']}e
        Spin: {m['spin']}
        Quantum state: n = {n}
    
    MASS ENERGY:
        E_K = (m_q1 + m_q̄2) × c² × exp(n/26)
        E_K = ({m['mass_eV'] / 1e6:.3f} MeV) × exp({n}/26)
        E_K = {m['mass_eV'] * 1.602e-19 * np.exp(n/26):.4e} J
    
    ENERGY DENSITY:
        U_K = {lambda_m} × {rho_SCm:.4e} × {rho_UA:.4e} × {omega_m:.2e}
              × {cos_term:.6f} × {1 + f_TRZ}
        U_K = {U_m:.4e} J/m³
    
    DECAY (Weak Force):
        Lifetime: τ = {tau:.4e} s
        Decay rate: Γ = 1/τ = {Gamma:.4e} Hz
        Γ(t) = (1/τ) × exp(-t/τ)"""
        
        return U_m, steps
    
    def compute_higgs_energy_density(self, t: float = 0) -> Tuple[float, str]:
        """
        Compute Higgs boson energy density in UQFF
        
        U_H = λ_H × ρ_vac,[UA] × ω_H(t) × exp(-[SSq]^n26 × exp(-π-t)) × (1+f_quasi)
        
        Also includes Higgs potential: V(φ) = μ²|φ|² + λ|φ|⁴
        
        Returns:
            Energy density and calculation steps
        """
        lambda_H = 1.0
        omega_H = CONSTANTS['omega_H']
        rho_UA = CONSTANTS['rho_vac_UA']
        f_quasi = CONSTANTS['f_quasi']
        n = self.bosons['Higgs']['quantum_state']
        
        nl_val, _ = self.compute_nonlocal_term(n, t)
        
        U_H = lambda_H * rho_UA * omega_H * np.exp(-nl_val) * (1 + f_quasi)
        
        # Higgs potential parameters
        mu_sq = CONSTANTS['mu_H_sq']
        lambda_quartic = CONSTANTS['lambda_H_quartic']
        v_H = CONSTANTS['v_H']
        
        steps = f"""
    Higgs Boson Energy Density in Aether
    ═══════════════════════════════════════════════════════════════════════════════
    
    EQUATION:
        U_H = λ_H × ρ_vac,[UA] × ω_H(t) × exp(-[SSq]^(n/26) × exp(-π-t)) × (1+f_quasi)
    
    HIGGS PARAMETERS:
        m_H = {CONSTANTS['m_H'] / 1e9:.2f} GeV/c²
        ω_H = {omega_H:.2e} rad/s (fluctuation frequency)
        Quantum state: n = {n}
        Width: Γ_H = {CONSTANTS['Gamma_H'] / 1e6:.2f} MeV
    
    ENERGY DENSITY:
        ρ_vac,[UA] = {rho_UA:.4e} J/m³
        Non-local term = {nl_val:.6e}
        exp(-nl_val) = {np.exp(-nl_val):.6f}
        f_quasi = {f_quasi}
        
        U_H = {lambda_H} × {rho_UA:.4e} × {omega_H:.2e}
              × {np.exp(-nl_val):.6f} × (1 + {f_quasi})
        U_H = {U_H:.4e} J/m³
    
    ═══════════════════════════════════════════════════════════════════════════════
    HIGGS POTENTIAL: V(φ) = ½μ²|φ|² + ¼λ|φ|⁴
    ═══════════════════════════════════════════════════════════════════════════════
        μ² = {mu_sq:.4e} eV² (negative → spontaneous symmetry breaking)
        λ = {lambda_quartic} (quartic self-coupling)
        v_H = {v_H / 1e9:.2f} GeV (vacuum expectation value)
    
    MASS GENERATION (Yukawa Coupling):
        m_f = y_f × v_H
        ─────────────────────────────────
        y_t (top)     = {CONSTANTS['y_t']:.4f} → m_t = {CONSTANTS['y_t'] * v_H / 1e9:.1f} GeV
        y_b (bottom)  = {CONSTANTS['y_b']:.4f} → m_b = {CONSTANTS['y_b'] * v_H / 1e9:.2f} GeV
        y_tau (tau)   = {CONSTANTS['y_tau']:.4f} → m_τ = {CONSTANTS['y_tau'] * v_H / 1e9 * 1000:.0f} MeV
        y_e (electron) = {CONSTANTS['y_e']:.2e} → m_e = {CONSTANTS['y_e'] * v_H / 1e6:.3f} MeV"""
        
        return U_H, steps
    
    def compute_proton_energy_density(self, t: float = 0) -> Tuple[float, str]:
        """
        Compute proton (uud) composite energy density
        
        U_p = Σ_{q ∈ {u,u,d}} U_q + U_g (gluon binding)
        
        Returns:
            Proton energy density and calculation steps
        """
        # Constituent quark contributions
        U_u, _ = self.compute_quark_energy_density('u', t)
        U_d, _ = self.compute_quark_energy_density('d', t)
        
        # Gluon binding
        U_g, _ = self.compute_gluon_energy_density(t)
        
        # Proton = uud
        U_p = 2 * U_u + U_d + U_g
        
        p = self.baryons['proton']
        
        # Mass energy
        E_p = p['mass_eV'] * 1.602e-19  # Convert to J
        n = p['quantum_state']
        E_p_UQFF = E_p * np.exp(n / 26)
        
        steps = f"""
    Proton (uud) Composite Energy Density
    ═══════════════════════════════════════════════════════════════════════════════
    
    EQUATION:
        U_p = Σ_{{q in {{u,u,d}}}} U_q + U_g
    
    PROTON STRUCTURE:
        Quark content: uud
        Mass: {p['mass_eV'] / 1e6:.3f} MeV/c² = {p['mass_kg']:.4e} kg
        Charge: {p['charge']}e (from +2/3 + 2/3 - 1/3)
        Spin: {p['spin']}
        Radius: {p['radius'] * 1e15:.4f} fm
        Magnetic moment: {p['magnetic_moment']} μ_N
    
    CONSTITUENT CONTRIBUTIONS:
        U_u (up quark) = {U_u:.4e} J/m³
        U_d (down quark) = {U_d:.4e} J/m³
        U_g (gluon binding) = {U_g:.4e} J/m³
    
    TOTAL:
        U_p = 2×U_u + U_d + U_g
        U_p = 2×{U_u:.4e} + {U_d:.4e} + {U_g:.4e}
        U_p = {U_p:.4e} J/m³
    
    UQFF MASS ENERGY:
        E_p = m_p × c² × exp(n/26)
        E_p (SM) = {E_p:.4e} J = {p['mass_eV'] / 1e6:.3f} MeV
        E_p (UQFF, n={n}) = {E_p_UQFF:.4e} J = {E_p_UQFF / 1.602e-19 / 1e6:.3f} MeV
    
    NOTE: ~99% of proton mass from gluon field energy, not quark rest mass!
    Quark masses: m_u + m_u + m_d ≈ 9 MeV, but m_p ≈ 938 MeV."""
        
        return U_p, steps
    
    def compute_neutron_energy_density(self, t: float = 0) -> Tuple[float, str]:
        """
        Compute neutron (udd) composite energy density
        
        U_n = Σ_{q ∈ {u,d,d}} U_q + U_g (gluon binding)
        
        Returns:
            Neutron energy density and calculation steps
        """
        # Constituent quark contributions
        U_u, _ = self.compute_quark_energy_density('u', t)
        U_d, _ = self.compute_quark_energy_density('d', t)
        
        # Gluon binding
        U_g, _ = self.compute_gluon_energy_density(t)
        
        # Neutron = udd
        U_n = U_u + 2 * U_d + U_g
        
        n_particle = self.baryons['neutron']
        
        # Mass-energy
        E_n = n_particle['mass_eV'] * 1.602e-19
        n_state = n_particle['quantum_state']
        E_n_UQFF = E_n * np.exp(n_state / 26)
        
        # Neutron decay: n → p + e⁻ + ν̄_e
        tau_n = n_particle['lifetime']
        Q_beta = (n_particle['mass_eV'] - CONSTANTS['m_p_eV'] - 0.511e6) / 1e6  # MeV
        
        steps = f"""
    Neutron (udd) Composite Energy Density
    ═══════════════════════════════════════════════════════════════════════════════
    
    EQUATION:
        U_n = Σ_{{q ∈ {{u,d,d}}}} U_q + U_g
    
    NEUTRON STRUCTURE:
        Quark content: udd
        Mass: {n_particle['mass_eV'] / 1e6:.3f} MeV/c²
        Charge: {n_particle['charge']}e (from +2/3 - 1/3 - 1/3)
        Spin: {n_particle['spin']}
        Magnetic moment: {n_particle['magnetic_moment']} μ_N
    
    CONSTITUENT CONTRIBUTIONS:
        U_u (up quark) = {U_u:.4e} J/m³
        U_d (down quark) = {U_d:.4e} J/m³
        U_g (gluon binding) = {U_g:.4e} J/m³
    
    TOTAL:
        U_n = U_u + 2×U_d + U_g
        U_n = {U_u:.4e} + 2×{U_d:.4e} + {U_g:.4e}
        U_n = {U_n:.4e} J/m³
    
    UQFF MASS ENERGY:
        E_n = m_n × c² × exp(n/26)
        E_n (SM) = {E_n:.4e} J = {n_particle['mass_eV'] / 1e6:.3f} MeV
        E_n (UQFF, n={n_state}) = {E_n_UQFF:.4e} J = {E_n_UQFF / 1.602e-19 / 1e6:.3f} MeV
    
    BETA DECAY (Free Neutron):
        n → p + e⁻ + ν̄_e
        Lifetime: τ_n = {tau_n:.1f} s = {tau_n / 60:.2f} min
        Q-value: {Q_beta:.3f} MeV"""
        
        return U_n, steps
    
    def compute_neutrino_oscillation(self, L: float, E_nu: float, 
                                      flavor_from: str = 'nu_e', 
                                      flavor_to: str = 'nu_mu') -> Tuple[float, str]:
        """
        Compute neutrino oscillation probability in [UA]
        
        P(ν_α → ν_β) = sin²(2θ) × sin²(Δm²L / 4E_ν)
        
        Parameters:
            L: Distance traveled (m)
            E_nu: Neutrino energy (J)
            flavor_from: 'nu_e', 'nu_mu', or 'nu_tau'
            flavor_to: 'nu_e', 'nu_mu', or 'nu_tau'
            
        Returns:
            Oscillation probability and calculation steps
        """
        # Select mixing angle
        if (flavor_from, flavor_to) in [('nu_e', 'nu_mu'), ('nu_mu', 'nu_e')]:
            theta = CONSTANTS['theta_12']
            delta_m_sq = CONSTANTS['delta_m21_sq'] * (1.602e-19)**2  # Convert eV² to J²
        elif (flavor_from, flavor_to) in [('nu_mu', 'nu_tau'), ('nu_tau', 'nu_mu')]:
            theta = CONSTANTS['theta_23']
            delta_m_sq = CONSTANTS['delta_m32_sq'] * (1.602e-19)**2
        else:
            theta = CONSTANTS['theta_13']
            delta_m_sq = CONSTANTS['delta_m32_sq'] * (1.602e-19)**2
        
        # P = sin²(2θ) × sin²(Δm²L / 4E)
        c = CONSTANTS['c']
        hbar = CONSTANTS['hbar']
        
        # Convert units for oscillation formula
        # Standard formula: P = sin²(2θ) × sin²(1.27 × Δm²[eV²] × L[km] / E[GeV])
        delta_m_sq_eV = CONSTANTS['delta_m21_sq'] if 'e' in flavor_from else CONSTANTS['delta_m32_sq']
        L_km = L / 1000
        E_GeV = E_nu / 1.602e-19 / 1e9
        
        phase = 1.27 * delta_m_sq_eV * L_km / E_GeV
        P_osc = np.sin(2 * theta)**2 * np.sin(phase)**2
        
        steps = f"""
    Neutrino Oscillation in [UA] ({flavor_from} → {flavor_to})
    ═══════════════════════════════════════════════════════════════════════════════
    
    EQUATION:
        P(ν_α → ν_β) = sin²(2θ) × sin²(1.27 × Δm² × L / E)
        
    PARAMETERS:
        Flavor transition: {flavor_from} → {flavor_to}
        θ (mixing angle) = {theta:.4f} rad = {np.degrees(theta):.2f}°
        Δm² = {delta_m_sq_eV:.4e} eV²
        L = {L:.2e} m = {L_km:.4f} km
        E_ν = {E_nu:.4e} J = {E_GeV:.4f} GeV
    
    CALCULATION:
        sin²(2θ) = sin²(2 × {theta:.4f}) = {np.sin(2 * theta)**2:.6f}
        Phase = 1.27 × {delta_m_sq_eV:.4e} × {L_km:.4f} / {E_GeV:.4f}
              = {phase:.4f} rad
        sin²(phase) = {np.sin(phase)**2:.6f}
    
    RESULT:
        P({flavor_from} → {flavor_to}) = {np.sin(2 * theta)**2:.6f} × {np.sin(phase)**2:.6f}
        P = {P_osc:.6f} = {P_osc * 100:.2f}%
    
    UQFF INTERPRETATION:
        Neutrinos oscillate between flavors as they propagate through [UA].
        This is modeled as transitions between quantum states in the Aether.
        Mixing angles measured by solar, atmospheric, and reactor experiments."""
        
        return P_osc, steps
    
