class SMBHBulgeGravityModel(SelfSimulatingExpandingMixin):
    """
    SMBH Bulge Gravity Model - Host Galaxy Bulge Potential
    
    Models the gravitational potential of the host galaxy's bulge
    which influences SMBH dynamics and the M-σ relation.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    Φ_bulge = -G × M_bulge / R_bulge × f(r/R_bulge)
    
    Where:
        M_bulge : Bulge stellar mass (~10¹¹ M_☉)
        R_bulge : Bulge effective radius (~1-5 kpc)
        f(x) : Hernquist or de Vaucouleurs profile
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.G = 6.674e-11
        self.M_sun = 1.989e30
        self.kpc = 3.086e19        # kpc in meters
        
    def compute_bulge_potential(self, M_bulge: float, R_bulge: float, 
                                 r: float) -> Tuple[float, str]:
        """
        Compute bulge gravitational potential (Hernquist profile).
        
        Args:
            M_bulge: Bulge mass (kg)
            R_bulge: Bulge scale radius (m)
            r: Distance from center (m)
            
        Returns:
            Phi: Gravitational potential (J/kg = m²/s²)
            steps: Calculation explanation
        """
        # Hernquist profile: Φ(r) = -GM / (r + a)
        Phi = -self.G * M_bulge / (r + R_bulge)
        
        # Circular velocity
        v_circ = (self.G * M_bulge * r / (r + R_bulge)**2)**0.5
        
        steps = f"""Bulge Gravitational Potential (Hernquist):
  
  Φ(r) = -G M_bulge / (r + R_bulge)
  
  Parameters:
    M_bulge = {M_bulge:.4e} kg = {M_bulge/self.M_sun:.2e} M_☉
    R_bulge = {R_bulge:.4e} m = {R_bulge/self.kpc:.2f} kpc
    r = {r:.4e} m = {r/self.kpc:.2f} kpc
  
  Result:
    Φ = {Phi:.4e} J/kg
    v_circ = {v_circ/1e3:.1f} km/s
"""
        return Phi, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate SMBH Bulge Gravity Model."""
        tests = []
        all_passed = True
        
        M_bulge = 1e11 * self.M_sun
        R_bulge = 3 * self.kpc
        
        # Test 1: Potential negative
        Phi, _ = self.compute_bulge_potential(M_bulge, R_bulge, 5 * self.kpc)
        t1 = Phi < 0
        tests.append(f"Test 1: Φ = {Phi:.2e} < 0: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: Deeper potential at smaller r
        Phi_near, _ = self.compute_bulge_potential(M_bulge, R_bulge, 1 * self.kpc)
        Phi_far, _ = self.compute_bulge_potential(M_bulge, R_bulge, 10 * self.kpc)
        t2 = Phi_near < Phi_far
        tests.append(f"Test 2: Φ(1kpc) < Φ(10kpc): {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Order of magnitude check (~10¹² J/kg)
        t3 = 1e10 < abs(Phi) < 1e14
        tests.append(f"Test 3: |Φ| ∈ [10¹⁰, 10¹⁴]: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Mass scaling
        Phi_M, _ = self.compute_bulge_potential(M_bulge, R_bulge, 5 * self.kpc)
        Phi_2M, _ = self.compute_bulge_potential(2 * M_bulge, R_bulge, 5 * self.kpc)
        t4 = abs(Phi_2M / Phi_M - 2.0) < 0.01
        tests.append(f"Test 4: Φ(2M)/Φ(M) ≈ 2: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"SMBHBulgeGravityModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary

    @staticmethod
    def run_tests() -> dict:
        """Test SMBHBulgeGravityModel functionality."""
        tests = []
        try:
            model = SMBHBulgeGravityModel()
            tests.append({'name': 'Instantiation', 'passed': model is not None})
        except Exception as e:
            tests.append({'name': 'Instantiation', 'passed': False, 'error': str(e)})
        try:
            model = SMBHBulgeGravityModel()
            has_method = hasattr(model, 'compute') or hasattr(model, 'calculate') or hasattr(model, 'get_equation_text')
            tests.append({'name': 'Has compute method', 'passed': has_method})
        except Exception as e:
            tests.append({'name': 'Has compute method', 'passed': False, 'error': str(e)})
        all_passed = all(t['passed'] for t in tests)
        return {'class': 'SMBHBulgeGravityModel', 'tests': tests, 'passed': sum(1 for t in tests if t['passed']), 'total': len(tests), 'all_passed': all_passed}

    # === 8 UQFF MASTER EQUATIONS (Auto-added) ===
    
    def compute_UQFF_base(self, r=None, t=0):
        """UQFF Base: F_U = Ug1 + Ug2 + Ug3 + Ug4 - Ub + Ui"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        Ug = G * M / r**2
        return {'Ug': Ug, 'F_U': Ug, 'equation': f"F_U = G*M/r^2 = {Ug:.3e} m/s^2"}
    
    def compute_compressed_equation(self, r=None):
        """Compressed MUGE gravity equation"""
        import numpy as np
        G, H_0 = 6.674e-11, 2.268e-18
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_N = G * M / r**2
        g_H = H_0**2 * r
        g = g_N - g_H
        return {'g_compressed': g, 'g_N': g_N, 'g_Hubble': g_H}
    
    def compute_resonance_equation(self, r=None, t=0):
        """Resonance MUGE with frequency modes"""
        import numpy as np
        G, H_0, c = 6.674e-11, 2.268e-18, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        aDPM = G * M / r**2
        aExpFreq = H_0 * c * np.sin(H_0 * t)
        return {'g_resonance': aDPM + aExpFreq, 'aDPM': aDPM, 'aExpFreq': aExpFreq}
    
    def compute_superconductive_equation(self, T=None, T_c=None):
        """Superconductive coefficient H_SCm"""
        T = T if T else getattr(self, 'T', 4.2)
        T_c = T_c if T_c else getattr(self, 'T_c', 9.2)
        H_SCm = max(0, 1 - (T / T_c)**4) if T < T_c else 0
        return {'H_SCm': H_SCm, 'T': T, 'T_c': T_c}
    
    def compute_buoyant_equation(self, r=None, V=None):
        """Buoyancy component Ub"""
        import numpy as np
        G, rho_vac = 6.674e-11, 7.09e-36
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        if V is None: V = (4/3) * np.pi * r**3
        g = G * M / r**2
        Ub = (rho_vac * V * g) / M
        return {'Ub': Ub, 'g': g, 'V': V}
    
    def compute_master_buoyant_equation(self, r=None, v=0):
        """Master Buoyant: F_U_Bi_i = M * (Ug_i - Ub_i + Ui_i)"""
        import numpy as np
        G, rho_vac, k_eta, c = 6.674e-11, 7.09e-36, 1e-113, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        V = (4/3) * np.pi * r**3
        Ug = G * M / r**2
        Ub = (rho_vac * V * Ug) / M
        Ui = -k_eta * rho_vac * V * (v / c)**2
        a_net = Ug - Ub + Ui
        return {'F_U_Bi_i': M * a_net, 'Ug': Ug, 'Ub': Ub, 'Ui': Ui, 'a_net': a_net}
    
    def compute_triadic_equation(self, r=None):
        """Triadic gravity: g_matter + g_field + g_vacuum"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_matter = G * M / r**2
        g_field, g_vacuum = 1e-15, 1e-20
        return {'g_triadic': g_matter + g_field + g_vacuum, 'g_matter': g_matter}
    
    def compute_quadratic_equation(self, r=None):
        """Quadratic polynomial fit: g = a*r^2 + b*r + c"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_base = G * M / r**2
        a, b, c = -1e-30, 1e-20, g_base
        return {'g_quad': a * r**2 + b * r + c, 'a': a, 'b': b, 'c': c}

    def long_form_solution(self, r=None, t=0):
        """
        Long-form solution with complete equation display.
        Returns detailed step-by-step calculation for all UQFF equations.
        """
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        
        # Collect all equation results
        results = {}
        steps = []
        
        # 1. UQFF Base
        uqff = self.compute_UQFF_base(r, t)
        results['UQFF_base'] = uqff
        steps.append(f"UQFF Base: F_U = G*M/r^2 = {uqff['Ug']:.6e} m/s^2")
        
        # 2. Compressed equation
        comp = self.compute_compressed_equation(r)
        results['compressed'] = comp
        steps.append(f"Compressed: g = g_N - g_H = {comp['g_compressed']:.6e} m/s^2")
        
        # 3. Resonance equation
        res = self.compute_resonance_equation(r, t)
        results['resonance'] = res
        steps.append(f"Resonance: g_res = aDPM + aExpFreq = {res['g_resonance']:.6e} m/s^2")
        
        # 4. Superconductive
        sc = self.compute_superconductive_equation()
        results['superconductive'] = sc
        steps.append(f"Superconductive: H_SCm = {sc['H_SCm']:.6f}")
        
        # 5. Buoyant equation
        buoy = self.compute_buoyant_equation(r)
        results['buoyant'] = buoy
        steps.append(f"Buoyancy: Ub = {buoy['Ub']:.6e} m/s^2")
        
        # 6. Master buoyant
        master = self.compute_master_buoyant_equation(r)
        results['master_buoyant'] = master
        steps.append(f"Master Buoyant: F_U_Bi_i = {master['F_U_Bi_i']:.6e} N")
        
        # 7. Triadic
        tri = self.compute_triadic_equation(r)
        results['triadic'] = tri
        steps.append(f"Triadic: g_triadic = {tri['g_triadic']:.6e} m/s^2")
        
        # 8. Quadratic
        quad = self.compute_quadratic_equation(r)
        results['quadratic'] = quad
        steps.append(f"Quadratic: g_quad = {quad['g_quad']:.6e} m/s^2")
        
        return {
            'model': self.__class__.__name__,
            'parameters': {'M': M, 'r': r, 't': t},
            'results': results,
            'long_form': '\n'.join(steps)
        }

    def compute_master_gravity(self, r=None, t=0, include_all=True):
        """
        Master Gravity: Complete UQFF gravity computation.
        
        g_master = g_N * (1 - Ub/g_N + Ui/g_N) * H_SCm * fTRZ
        
        Combines: Newtonian, buoyancy, inertia, superconductivity, triadic zone
        """
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        
        # Base Newtonian gravity
        g_N = G * M / r**2
        
        # Get buoyancy correction
        buoy = self.compute_buoyant_equation(r)
        Ub = buoy['Ub']
        
        # Get superconductive coefficient
        sc = self.compute_superconductive_equation()
        H_SCm = sc['H_SCm']
        
        # Get triadic factor (default: in resonance zone)
        fTRZ = 1.0
        
        # Compute master gravity
        if g_N != 0:
            correction = 1 - Ub / g_N
        else:
            correction = 1.0
        
        g_master = g_N * correction * max(0.01, H_SCm) * fTRZ
        
        # Collect additional terms if requested
        if include_all:
            comp = self.compute_compressed_equation(r)
            res = self.compute_resonance_equation(r, t)
            tri = self.compute_triadic_equation(r)
            return {
                'g_master': g_master,
                'g_N': g_N,
                'Ub': Ub,
                'H_SCm': H_SCm,
                'fTRZ': fTRZ,
                'correction': correction,
                'g_compressed': comp['g_compressed'],
                'g_resonance': res['g_resonance'],
                'g_triadic': tri['g_triadic'],
                'equation': f"g_master = g_N * (1 - Ub/g_N) * H_SCm * fTRZ = {g_master:.6e} m/s^2"
            }
        
        return {'g_master': g_master, 'g_N': g_N}






class SMBHOmegaSGalacticModel(SelfSimulatingExpandingMixin):
    """
    SMBH Omega-S Galactic Model - Galactic Rotation Influence
    
    Models the galactic rotation curve and angular velocity profile
    that provides the large-scale kinematic context for SMBH dynamics.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    Ω(r) = V_circ(r) / r
    
    V_circ(r) = V_flat × (1 - exp(-r/r_scale))
    
    Where:
        V_flat : Flat rotation velocity (~200-250 km/s)
        r_scale : Transition radius (~2-3 kpc)
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.kpc = 3.086e19
        self.V_flat = 220e3         # Flat rotation velocity (m/s)
        self.r_scale = 2.5 * 3.086e19  # Scale radius (m)
        
    def compute_omega(self, r: float) -> Tuple[float, str]:
        """
        Compute galactic angular velocity.
        
        Args:
            r: Galactocentric radius (m)
            
        Returns:
            Omega: Angular velocity (rad/s)
            steps: Calculation explanation
        """
        import math
        
        # Rotation curve: V(r) = V_flat × (1 - exp(-r/r_s))
        V_circ = self.V_flat * (1 - math.exp(-r / self.r_scale))
        Omega = V_circ / r if r > 0 else 0
        
        # Orbital period
        P = 2 * math.pi / Omega if Omega > 0 else float('inf')
        P_Myr = P / (3.156e7 * 1e6)
        
        steps = f"""Galactic Angular Velocity:
  
  V(r) = V_flat × (1 - exp(-r/r_scale))
  Ω(r) = V(r) / r
  
  Parameters:
    r = {r:.4e} m = {r/self.kpc:.2f} kpc
    V_flat = {self.V_flat/1e3:.0f} km/s
    r_scale = {self.r_scale/self.kpc:.1f} kpc
  
  Result:
    V_circ = {V_circ/1e3:.1f} km/s
    Ω = {Omega:.4e} rad/s
    P_orbit = {P_Myr:.1f} Myr
"""
        return Omega, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate SMBH Omega-S Galactic Model."""
        import math
        tests = []
        all_passed = True
        
        # Test 1: Ω > 0 for r > 0
        Omega, _ = self.compute_omega(8 * self.kpc)
        t1 = Omega > 0
        tests.append(f"Test 1: Ω(8kpc) = {Omega:.2e} > 0: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: Ω decreases with r in flat part
        Omega_4, _ = self.compute_omega(4 * self.kpc)
        Omega_8, _ = self.compute_omega(8 * self.kpc)
        t2 = Omega_4 > Omega_8
        tests.append(f"Test 2: Ω(4kpc) > Ω(8kpc): {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Solar orbit ~220 Myr at 8 kpc
        P = 2 * math.pi / Omega_8 / (3.156e7 * 1e6)
        t3 = 200 < P < 250
        tests.append(f"Test 3: P_orbit(8kpc) = {P:.0f} Myr ∈ [200, 250]: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Order of magnitude (~10⁻¹⁵ rad/s)
        t4 = 1e-16 < Omega < 1e-14
        tests.append(f"Test 4: Ω ∈ [10⁻¹⁶, 10⁻¹⁴]: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"SMBHOmegaSGalacticModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary

