class VirgoClusterMassModel(SelfSimulatingExpandingMixin):
    """
    Virgo Cluster Mass Model - Total Cluster Mass Distribution
    
    Models the mass distribution of the Virgo cluster, the nearest
    massive galaxy cluster at ~16.5 Mpc.
    
    KEY PARAMETERS:
    ─────────────────────────────────────────────────────────────────────────────
    
    M_virial ≈ 1.2 × 10¹⁵ M_☉
    R_virial ≈ 1.55 Mpc
    σ_v ≈ 700 km/s (velocity dispersion)
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.G = 6.674e-11
        self.M_sun = 1.989e30
        self.Mpc = 3.086e22
        self.M_virial = 1.2e15 * 1.989e30  # kg
        self.R_virial = 1.55 * 3.086e22     # m
        
    def compute_enclosed_mass(self, r: float, profile: str = 'NFW') -> Tuple[float, str]:
        """
        Compute enclosed mass at radius r.
        
        Args:
            r: Radius from cluster center (m)
            profile: 'NFW' or 'isothermal'
            
        Returns:
            M_enc: Enclosed mass (kg)
            steps: Calculation explanation
        """
        import math
        
        r_s = 0.2 * self.R_virial  # Scale radius
        
        if profile == 'NFW':
            # NFW: M(<r) = M_0 × [ln(1 + r/r_s) - r/(r+r_s)]
            x = r / r_s
            f_x = math.log(1 + x) - x / (1 + x)
            f_virial = math.log(1 + 5) - 5/6  # at c=5
            M_enc = self.M_virial * f_x / f_virial
        else:
            # Isothermal: M(<r) ∝ r
            M_enc = self.M_virial * r / self.R_virial
        
        steps = f"""Virgo Cluster Enclosed Mass ({profile}):
  
  Parameters:
    r = {r:.4e} m = {r/self.Mpc:.2f} Mpc
    R_virial = {self.R_virial/self.Mpc:.2f} Mpc
    M_virial = {self.M_virial/self.M_sun:.2e} M_☉
  
  Result:
    M(<r) = {M_enc:.4e} kg = {M_enc/self.M_sun:.2e} M_☉
"""
        return M_enc, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Virgo Cluster Mass Model."""
        tests = []
        all_passed = True
        
        # Test 1: M(R_virial) ≈ M_virial
        M_enc, _ = self.compute_enclosed_mass(self.R_virial)
        t1 = 0.5 < M_enc / self.M_virial < 1.5
        tests.append(f"Test 1: M(R_vir)/M_vir = {M_enc/self.M_virial:.2f} ∈ [0.5, 1.5]: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: Mass increases with r
        M_1, _ = self.compute_enclosed_mass(0.5 * self.R_virial)
        M_2, _ = self.compute_enclosed_mass(self.R_virial)
        t2 = M_2 > M_1
        tests.append(f"Test 2: M(R_vir) > M(0.5 R_vir): {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Cluster mass order of magnitude
        t3 = 1e14 < self.M_virial / self.M_sun < 1e16
        tests.append(f"Test 3: M_vir ∈ [10¹⁴, 10¹⁶] M_☉: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: M > 0 everywhere
        M_small, _ = self.compute_enclosed_mass(0.1 * self.Mpc)
        t4 = M_small > 0
        tests.append(f"Test 4: M(0.1 Mpc) > 0: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"VirgoClusterMassModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary

    @staticmethod
    def run_tests() -> dict:
        """Test VirgoClusterMassModel functionality."""
        tests = []
        try:
            model = VirgoClusterMassModel()
            tests.append({'name': 'Instantiation', 'passed': model is not None})
        except Exception as e:
            tests.append({'name': 'Instantiation', 'passed': False, 'error': str(e)})
        try:
            model = VirgoClusterMassModel()
            has_method = hasattr(model, 'compute') or hasattr(model, 'calculate') or hasattr(model, 'get_equation_text')
            tests.append({'name': 'Has compute method', 'passed': has_method})
        except Exception as e:
            tests.append({'name': 'Has compute method', 'passed': False, 'error': str(e)})
        all_passed = all(t['passed'] for t in tests)
        return {'class': 'VirgoClusterMassModel', 'tests': tests, 'passed': sum(1 for t in tests if t['passed']), 'total': len(tests), 'all_passed': all_passed}

    # === 8 UQFF MASTER EQUATIONS (Auto-added) ===
    
    def compute_UQFF_base(self, r=None, t=0):
        """UQFF Base: F_U = Ug1 + Ug2 + Ug3 + Ug4 - Ub + Ui"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        Ug = G * M / r**2
        return {'Ug': Ug, 'F_U': Ug, 'equation': f"F_U = G*M/r^2 = {Ug:.3e} m/s^2"}
    
    def compute_compressed_equation(self, r=None):
        """Compressed MUGE gravity equation"""
        import numpy as np
        G, H_0 = 6.674e-11, 2.268e-18
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_N = G * M / r**2
        g_H = H_0**2 * r
        g = g_N - g_H
        return {'g_compressed': g, 'g_N': g_N, 'g_Hubble': g_H}
    
    def compute_resonance_equation(self, r=None, t=0):
        """Resonance MUGE with frequency modes"""
        import numpy as np
        G, H_0, c = 6.674e-11, 2.268e-18, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        aDPM = G * M / r**2
        aExpFreq = H_0 * c * np.sin(H_0 * t)
        return {'g_resonance': aDPM + aExpFreq, 'aDPM': aDPM, 'aExpFreq': aExpFreq}
    
    def compute_superconductive_equation(self, T=None, T_c=None):
        """Superconductive coefficient H_SCm"""
        T = T if T else getattr(self, 'T', 4.2)
        T_c = T_c if T_c else getattr(self, 'T_c', 9.2)
        H_SCm = max(0, 1 - (T / T_c)**4) if T < T_c else 0
        return {'H_SCm': H_SCm, 'T': T, 'T_c': T_c}
    
    def compute_buoyant_equation(self, r=None, V=None):
        """Buoyancy component Ub"""
        import numpy as np
        G, rho_vac = 6.674e-11, 7.09e-36
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        if V is None: V = (4/3) * np.pi * r**3
        g = G * M / r**2
        Ub = (rho_vac * V * g) / M
        return {'Ub': Ub, 'g': g, 'V': V}
    
    def compute_master_buoyant_equation(self, r=None, v=0):
        """Master Buoyant: F_U_Bi_i = M * (Ug_i - Ub_i + Ui_i)"""
        import numpy as np
        G, rho_vac, k_eta, c = 6.674e-11, 7.09e-36, 1e-113, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        V = (4/3) * np.pi * r**3
        Ug = G * M / r**2
        Ub = (rho_vac * V * Ug) / M
        Ui = -k_eta * rho_vac * V * (v / c)**2
        a_net = Ug - Ub + Ui
        return {'F_U_Bi_i': M * a_net, 'Ug': Ug, 'Ub': Ub, 'Ui': Ui, 'a_net': a_net}
    
    def compute_triadic_equation(self, r=None):
        """Triadic gravity: g_matter + g_field + g_vacuum"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_matter = G * M / r**2
        g_field, g_vacuum = 1e-15, 1e-20
        return {'g_triadic': g_matter + g_field + g_vacuum, 'g_matter': g_matter}
    
    def compute_quadratic_equation(self, r=None):
        """Quadratic polynomial fit: g = a*r^2 + b*r + c"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_base = G * M / r**2
        a, b, c = -1e-30, 1e-20, g_base
        return {'g_quad': a * r**2 + b * r + c, 'a': a, 'b': b, 'c': c}

    def long_form_solution(self, r=None, t=0):
        """
        Long-form solution with complete equation display.
        Returns detailed step-by-step calculation for all UQFF equations.
        """
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        
        # Collect all equation results
        results = {}
        steps = []
        
        # 1. UQFF Base
        uqff = self.compute_UQFF_base(r, t)
        results['UQFF_base'] = uqff
        steps.append(f"UQFF Base: F_U = G*M/r^2 = {uqff['Ug']:.6e} m/s^2")
        
        # 2. Compressed equation
        comp = self.compute_compressed_equation(r)
        results['compressed'] = comp
        steps.append(f"Compressed: g = g_N - g_H = {comp['g_compressed']:.6e} m/s^2")
        
        # 3. Resonance equation
        res = self.compute_resonance_equation(r, t)
        results['resonance'] = res
        steps.append(f"Resonance: g_res = aDPM + aExpFreq = {res['g_resonance']:.6e} m/s^2")
        
        # 4. Superconductive
        sc = self.compute_superconductive_equation()
        results['superconductive'] = sc
        steps.append(f"Superconductive: H_SCm = {sc['H_SCm']:.6f}")
        
        # 5. Buoyant equation
        buoy = self.compute_buoyant_equation(r)
        results['buoyant'] = buoy
        steps.append(f"Buoyancy: Ub = {buoy['Ub']:.6e} m/s^2")
        
        # 6. Master buoyant
        master = self.compute_master_buoyant_equation(r)
        results['master_buoyant'] = master
        steps.append(f"Master Buoyant: F_U_Bi_i = {master['F_U_Bi_i']:.6e} N")
        
        # 7. Triadic
        tri = self.compute_triadic_equation(r)
        results['triadic'] = tri
        steps.append(f"Triadic: g_triadic = {tri['g_triadic']:.6e} m/s^2")
        
        # 8. Quadratic
        quad = self.compute_quadratic_equation(r)
        results['quadratic'] = quad
        steps.append(f"Quadratic: g_quad = {quad['g_quad']:.6e} m/s^2")
        
        return {
            'model': self.__class__.__name__,
            'parameters': {'M': M, 'r': r, 't': t},
            'results': results,
            'long_form': '\n'.join(steps)
        }

    def compute_master_gravity(self, r=None, t=0, include_all=True):
        """
        Master Gravity: Complete UQFF gravity computation.
        
        g_master = g_N * (1 - Ub/g_N + Ui/g_N) * H_SCm * fTRZ
        
        Combines: Newtonian, buoyancy, inertia, superconductivity, triadic zone
        """
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        
        # Base Newtonian gravity
        g_N = G * M / r**2
        
        # Get buoyancy correction
        buoy = self.compute_buoyant_equation(r)
        Ub = buoy['Ub']
        
        # Get superconductive coefficient
        sc = self.compute_superconductive_equation()
        H_SCm = sc['H_SCm']
        
        # Get triadic factor (default: in resonance zone)
        fTRZ = 1.0
        
        # Compute master gravity
        if g_N != 0:
            correction = 1 - Ub / g_N
        else:
            correction = 1.0
        
        g_master = g_N * correction * max(0.01, H_SCm) * fTRZ
        
        # Collect additional terms if requested
        if include_all:
            comp = self.compute_compressed_equation(r)
            res = self.compute_resonance_equation(r, t)
            tri = self.compute_triadic_equation(r)
            return {
                'g_master': g_master,
                'g_N': g_N,
                'Ub': Ub,
                'H_SCm': H_SCm,
                'fTRZ': fTRZ,
                'correction': correction,
                'g_compressed': comp['g_compressed'],
                'g_resonance': res['g_resonance'],
                'g_triadic': tri['g_triadic'],
                'equation': f"g_master = g_N * (1 - Ub/g_N) * H_SCm * fTRZ = {g_master:.6e} m/s^2"
            }
        
        return {'g_master': g_master, 'g_N': g_N}






class VirgoClusterDarkMatterModel(SelfSimulatingExpandingMixin):
    """
    Virgo Cluster Dark Matter Model - NFW Halo Profile
    
    Models the dark matter halo of the Virgo cluster using
    the Navarro-Frenk-White (NFW) density profile.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    ρ_DM(r) = ρ_s / [(r/r_s) × (1 + r/r_s)²]
    
    Where:
        ρ_s : Scale density (~10⁻²³ kg/m³)
        r_s : Scale radius (~300 kpc)
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.M_sun = 1.989e30
        self.kpc = 3.086e19
        self.r_s = 300 * 3.086e19   # Scale radius (300 kpc)
        self.rho_s = 1e-23          # Scale density (kg/m³)
        
    def compute_nfw_density(self, r: float) -> Tuple[float, str]:
        """
        Compute NFW dark matter density at radius r.
        
        Args:
            r: Radius from center (m)
            
        Returns:
            rho: Dark matter density (kg/m³)
            steps: Calculation explanation
        """
        x = r / self.r_s
        rho = self.rho_s / (x * (1 + x)**2)
        
        steps = f"""NFW Dark Matter Density:
  
  ρ(r) = ρ_s / [(r/r_s)(1 + r/r_s)²]
  
  Parameters:
    r = {r:.4e} m = {r/self.kpc:.1f} kpc
    r_s = {self.r_s/self.kpc:.0f} kpc
    ρ_s = {self.rho_s:.4e} kg/m³
  
  Result:
    ρ_DM = {rho:.4e} kg/m³
"""
        return rho, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Virgo Dark Matter Model."""
        tests = []
        all_passed = True
        
        # Test 1: Density positive
        rho, _ = self.compute_nfw_density(100 * self.kpc)
        t1 = rho > 0
        tests.append(f"Test 1: ρ(100 kpc) = {rho:.2e} > 0: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: Density decreases with r
        rho_1, _ = self.compute_nfw_density(100 * self.kpc)
        rho_2, _ = self.compute_nfw_density(500 * self.kpc)
        t2 = rho_1 > rho_2
        tests.append(f"Test 2: ρ(100 kpc) > ρ(500 kpc): {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Order of magnitude (10⁻²⁷ to 10⁻²⁰)
        t3 = 1e-28 < rho < 1e-20
        tests.append(f"Test 3: ρ ∈ [10⁻²⁸, 10⁻²⁰]: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: ρ(r_s) = ρ_s/4
        rho_rs, _ = self.compute_nfw_density(self.r_s)
        t4 = abs(rho_rs / (self.rho_s / 4) - 1) < 0.01
        tests.append(f"Test 4: ρ(r_s) = ρ_s/4: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"VirgoClusterDarkMatterModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary

    @staticmethod
    def run_tests() -> dict:
        """Test VirgoClusterDarkMatterModel functionality."""
        tests = []
        try:
            model = VirgoClusterDarkMatterModel()
            tests.append({'name': 'Instantiation', 'passed': model is not None})
        except Exception as e:
            tests.append({'name': 'Instantiation', 'passed': False, 'error': str(e)})
        try:
            model = VirgoClusterDarkMatterModel()
            has_method = hasattr(model, 'compute') or hasattr(model, 'calculate') or hasattr(model, 'get_equation_text')
            tests.append({'name': 'Has compute method', 'passed': has_method})
        except Exception as e:
            tests.append({'name': 'Has compute method', 'passed': False, 'error': str(e)})
        all_passed = all(t['passed'] for t in tests)
        return {'class': 'VirgoClusterDarkMatterModel', 'tests': tests, 'passed': sum(1 for t in tests if t['passed']), 'total': len(tests), 'all_passed': all_passed}

