class VirgoClusterVirialModel(SelfSimulatingExpandingMixin):
    """
    Virgo Cluster Virial Model - Virial Mass Estimation
    
    Models virial equilibrium for cluster mass estimation from
    velocity dispersion measurements.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    M_virial = (3/G) × σ_v² × R_virial
    
    Where:
        σ_v : Line-of-sight velocity dispersion (~700 km/s)
        R_virial : Virial radius (~1.55 Mpc)
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.G = 6.674e-11
        self.M_sun = 1.989e30
        self.Mpc = 3.086e22
        self.sigma_v = 700e3        # velocity dispersion (m/s)
        self.R_virial = 1.55 * 3.086e22
        
    def compute_virial_mass(self, sigma_v: float = None, 
                            R_virial: float = None) -> Tuple[float, str]:
        """
        Compute virial mass from velocity dispersion.
        
        Args:
            sigma_v: Velocity dispersion (m/s)
            R_virial: Virial radius (m)
            
        Returns:
            M_virial: Virial mass (kg)
            steps: Calculation explanation
        """
        if sigma_v is None:
            sigma_v = self.sigma_v
        if R_virial is None:
            R_virial = self.R_virial
        
        # M = 3 σ² R / G
        M_virial = 3 * sigma_v**2 * R_virial / self.G
        
        steps = f"""Virial Mass:
  
  M_virial = 3 σ_v² R_virial / G
  
  Parameters:
    σ_v = {sigma_v/1e3:.0f} km/s
    R_virial = {R_virial/self.Mpc:.2f} Mpc
  
  Result:
    M_virial = {M_virial:.4e} kg = {M_virial/self.M_sun:.2e} M_☉
"""
        return M_virial, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Virgo Virial Model."""
        tests = []
        all_passed = True
        
        # Test 1: M > 0
        M, _ = self.compute_virial_mass()
        t1 = M > 0
        tests.append(f"Test 1: M = {M/self.M_sun:.2e} M_☉ > 0: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: Cluster mass ~10¹⁴-10¹⁵ M_☉
        t2 = 1e14 < M / self.M_sun < 1e16
        tests.append(f"Test 2: M ∈ [10¹⁴, 10¹⁶] M_☉: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: σ² scaling
        M_1, _ = self.compute_virial_mass(sigma_v=500e3)
        M_2, _ = self.compute_virial_mass(sigma_v=1000e3)
        t3 = abs(M_2 / M_1 - 4.0) < 0.1
        tests.append(f"Test 3: M(2σ)/M(σ) ≈ 4: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: R scaling
        M_1, _ = self.compute_virial_mass(R_virial=1 * self.Mpc)
        M_2, _ = self.compute_virial_mass(R_virial=2 * self.Mpc)
        t4 = abs(M_2 / M_1 - 2.0) < 0.1
        tests.append(f"Test 4: M(2R)/M(R) ≈ 2: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"VirgoClusterVirialModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary

    @staticmethod
    def run_tests() -> dict:
        """Test VirgoClusterVirialModel functionality."""
        tests = []
        try:
            model = VirgoClusterVirialModel()
            tests.append({'name': 'Instantiation', 'passed': model is not None})
        except Exception as e:
            tests.append({'name': 'Instantiation', 'passed': False, 'error': str(e)})
        try:
            model = VirgoClusterVirialModel()
            has_method = hasattr(model, 'compute') or hasattr(model, 'calculate') or hasattr(model, 'get_equation_text')
            tests.append({'name': 'Has compute method', 'passed': has_method})
        except Exception as e:
            tests.append({'name': 'Has compute method', 'passed': False, 'error': str(e)})
        all_passed = all(t['passed'] for t in tests)
        return {'class': 'VirgoClusterVirialModel', 'tests': tests, 'passed': sum(1 for t in tests if t['passed']), 'total': len(tests), 'all_passed': all_passed}

    # === 8 UQFF MASTER EQUATIONS (Auto-added) ===
    
    def compute_UQFF_base(self, r=None, t=0):
        """UQFF Base: F_U = Ug1 + Ug2 + Ug3 + Ug4 - Ub + Ui"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        Ug = G * M / r**2
        return {'Ug': Ug, 'F_U': Ug, 'equation': f"F_U = G*M/r^2 = {Ug:.3e} m/s^2"}
    
    def compute_compressed_equation(self, r=None):
        """Compressed MUGE gravity equation"""
        import numpy as np
        G, H_0 = 6.674e-11, 2.268e-18
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_N = G * M / r**2
        g_H = H_0**2 * r
        g = g_N - g_H
        return {'g_compressed': g, 'g_N': g_N, 'g_Hubble': g_H}
    
    def compute_resonance_equation(self, r=None, t=0):
        """Resonance MUGE with frequency modes"""
        import numpy as np
        G, H_0, c = 6.674e-11, 2.268e-18, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        aDPM = G * M / r**2
        aExpFreq = H_0 * c * np.sin(H_0 * t)
        return {'g_resonance': aDPM + aExpFreq, 'aDPM': aDPM, 'aExpFreq': aExpFreq}
    
    def compute_superconductive_equation(self, T=None, T_c=None):
        """Superconductive coefficient H_SCm"""
        T = T if T else getattr(self, 'T', 4.2)
        T_c = T_c if T_c else getattr(self, 'T_c', 9.2)
        H_SCm = max(0, 1 - (T / T_c)**4) if T < T_c else 0
        return {'H_SCm': H_SCm, 'T': T, 'T_c': T_c}
    
    def compute_buoyant_equation(self, r=None, V=None):
        """Buoyancy component Ub"""
        import numpy as np
        G, rho_vac = 6.674e-11, 7.09e-36
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        if V is None: V = (4/3) * np.pi * r**3
        g = G * M / r**2
        Ub = (rho_vac * V * g) / M
        return {'Ub': Ub, 'g': g, 'V': V}
    
    def compute_master_buoyant_equation(self, r=None, v=0):
        """Master Buoyant: F_U_Bi_i = M * (Ug_i - Ub_i + Ui_i)"""
        import numpy as np
        G, rho_vac, k_eta, c = 6.674e-11, 7.09e-36, 1e-113, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        V = (4/3) * np.pi * r**3
        Ug = G * M / r**2
        Ub = (rho_vac * V * Ug) / M
        Ui = -k_eta * rho_vac * V * (v / c)**2
        a_net = Ug - Ub + Ui
        return {'F_U_Bi_i': M * a_net, 'Ug': Ug, 'Ub': Ub, 'Ui': Ui, 'a_net': a_net}
    
    def compute_triadic_equation(self, r=None):
        """Triadic gravity: g_matter + g_field + g_vacuum"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_matter = G * M / r**2
        g_field, g_vacuum = 1e-15, 1e-20
        return {'g_triadic': g_matter + g_field + g_vacuum, 'g_matter': g_matter}
    
    def compute_quadratic_equation(self, r=None):
        """Quadratic polynomial fit: g = a*r^2 + b*r + c"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_base = G * M / r**2
        a, b, c = -1e-30, 1e-20, g_base
        return {'g_quad': a * r**2 + b * r + c, 'a': a, 'b': b, 'c': c}

    def long_form_solution(self, r=None, t=0):
        """
        Long-form solution with complete equation display.
        Returns detailed step-by-step calculation for all UQFF equations.
        """
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        
        # Collect all equation results
        results = {}
        steps = []
        
        # 1. UQFF Base
        uqff = self.compute_UQFF_base(r, t)
        results['UQFF_base'] = uqff
        steps.append(f"UQFF Base: F_U = G*M/r^2 = {uqff['Ug']:.6e} m/s^2")
        
        # 2. Compressed equation
        comp = self.compute_compressed_equation(r)
        results['compressed'] = comp
        steps.append(f"Compressed: g = g_N - g_H = {comp['g_compressed']:.6e} m/s^2")
        
        # 3. Resonance equation
        res = self.compute_resonance_equation(r, t)
        results['resonance'] = res
        steps.append(f"Resonance: g_res = aDPM + aExpFreq = {res['g_resonance']:.6e} m/s^2")
        
        # 4. Superconductive
        sc = self.compute_superconductive_equation()
        results['superconductive'] = sc
        steps.append(f"Superconductive: H_SCm = {sc['H_SCm']:.6f}")
        
        # 5. Buoyant equation
        buoy = self.compute_buoyant_equation(r)
        results['buoyant'] = buoy
        steps.append(f"Buoyancy: Ub = {buoy['Ub']:.6e} m/s^2")
        
        # 6. Master buoyant
        master = self.compute_master_buoyant_equation(r)
        results['master_buoyant'] = master
        steps.append(f"Master Buoyant: F_U_Bi_i = {master['F_U_Bi_i']:.6e} N")
        
        # 7. Triadic
        tri = self.compute_triadic_equation(r)
        results['triadic'] = tri
        steps.append(f"Triadic: g_triadic = {tri['g_triadic']:.6e} m/s^2")
        
        # 8. Quadratic
        quad = self.compute_quadratic_equation(r)
        results['quadratic'] = quad
        steps.append(f"Quadratic: g_quad = {quad['g_quad']:.6e} m/s^2")
        
        return {
            'model': self.__class__.__name__,
            'parameters': {'M': M, 'r': r, 't': t},
            'results': results,
            'long_form': '\n'.join(steps)
        }

    def compute_master_gravity(self, r=None, t=0, include_all=True):
        """
        Master Gravity: Complete UQFF gravity computation.
        
        g_master = g_N * (1 - Ub/g_N + Ui/g_N) * H_SCm * fTRZ
        
        Combines: Newtonian, buoyancy, inertia, superconductivity, triadic zone
        """
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        
        # Base Newtonian gravity
        g_N = G * M / r**2
        
        # Get buoyancy correction
        buoy = self.compute_buoyant_equation(r)
        Ub = buoy['Ub']
        
        # Get superconductive coefficient
        sc = self.compute_superconductive_equation()
        H_SCm = sc['H_SCm']
        
        # Get triadic factor (default: in resonance zone)
        fTRZ = 1.0
        
        # Compute master gravity
        if g_N != 0:
            correction = 1 - Ub / g_N
        else:
            correction = 1.0
        
        g_master = g_N * correction * max(0.01, H_SCm) * fTRZ
        
        # Collect additional terms if requested
        if include_all:
            comp = self.compute_compressed_equation(r)
            res = self.compute_resonance_equation(r, t)
            tri = self.compute_triadic_equation(r)
            return {
                'g_master': g_master,
                'g_N': g_N,
                'Ub': Ub,
                'H_SCm': H_SCm,
                'fTRZ': fTRZ,
                'correction': correction,
                'g_compressed': comp['g_compressed'],
                'g_resonance': res['g_resonance'],
                'g_triadic': tri['g_triadic'],
                'equation': f"g_master = g_N * (1 - Ub/g_N) * H_SCm * fTRZ = {g_master:.6e} m/s^2"
            }
        
        return {'g_master': g_master, 'g_N': g_N}






class VirgoClusterICMModel(SelfSimulatingExpandingMixin):
    """
    Virgo Cluster Intracluster Medium (ICM) Model
    
    Models the hot gas properties of the intracluster medium,
    which dominates the baryonic mass of the cluster.
    
    KEY PARAMETERS:
    ─────────────────────────────────────────────────────────────────────────────
    
    T_ICM ≈ 2.3 keV (~2.7 × 10⁷ K)
    n_e ≈ 10⁻³ cm⁻³ central electron density
    M_gas ≈ 10¹³-10¹⁴ M_☉
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.M_sun = 1.989e30
        self.kpc = 3.086e19
        self.k_B = 1.381e-23        # Boltzmann
        self.keV = 1.602e-16        # keV to J
        self.T_ICM = 2.3 * self.keV / self.k_B  # K
        self.n_e0 = 1e3             # Central electron density (m⁻³)
        self.r_c = 50 * self.kpc    # Core radius
        self.beta = 0.5             # Beta model parameter
        
    def compute_electron_density(self, r: float) -> Tuple[float, str]:
        """
        Compute electron density at radius r (beta model).
        
        Args:
            r: Radius from center (m)
            
        Returns:
            n_e: Electron density (m⁻³)
            steps: Calculation explanation
        """
        # Beta model: n_e(r) = n_e0 × (1 + (r/r_c)²)^(-3β/2)
        n_e = self.n_e0 * (1 + (r / self.r_c)**2)**(-1.5 * self.beta)
        
        steps = f"""ICM Electron Density (β-model):
  
  n_e(r) = n_e0 × (1 + (r/r_c)²)^(-3β/2)
  
  Parameters:
    r = {r:.4e} m = {r/self.kpc:.1f} kpc
    n_e0 = {self.n_e0:.4e} m⁻³
    r_c = {self.r_c/self.kpc:.1f} kpc
    β = {self.beta}
  
  Result:
    n_e = {n_e:.4e} m⁻³ = {n_e/1e6:.4f} cm⁻³
"""
        return n_e, steps
    
    def compute_thermal_pressure(self, r: float) -> Tuple[float, str]:
        """
        Compute thermal pressure of ICM.
        
        Args:
            r: Radius from center (m)
            
        Returns:
            P: Thermal pressure (Pa)
            steps: Calculation explanation
        """
        n_e, _ = self.compute_electron_density(r)
        
        # P = n_e × k_B × T (plus ion contribution ~2×)
        P = 2.0 * n_e * self.k_B * self.T_ICM
        
        steps = f"""ICM Thermal Pressure:
  
  P = 2 n_e k_B T
  
  Parameters:
    n_e = {n_e:.4e} m⁻³
    T = {self.T_ICM:.4e} K = {self.T_ICM * self.k_B / self.keV:.1f} keV
  
  Result:
    P = {P:.4e} Pa
"""
        return P, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Virgo ICM Model."""
        tests = []
        all_passed = True
        
        # Test 1: Central n_e reasonable
        n_e, _ = self.compute_electron_density(0)
        t1 = abs(n_e - self.n_e0) < 1
        tests.append(f"Test 1: n_e(0) = {n_e:.2e} ≈ n_e0: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: Density decreases with r
        n_e_1, _ = self.compute_electron_density(50 * self.kpc)
        n_e_2, _ = self.compute_electron_density(200 * self.kpc)
        t2 = n_e_1 > n_e_2
        tests.append(f"Test 2: n_e(50 kpc) > n_e(200 kpc): {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Temperature ~10⁷ K
        t3 = 1e7 < self.T_ICM < 1e8
        tests.append(f"Test 3: T = {self.T_ICM:.2e} K ∈ [10⁷, 10⁸]: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Pressure > 0
        P, _ = self.compute_thermal_pressure(100 * self.kpc)
        t4 = P > 0
        tests.append(f"Test 4: P = {P:.2e} Pa > 0: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"VirgoClusterICMModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary

    @staticmethod
    def run_tests() -> dict:
        """Test VirgoClusterICMModel functionality."""
        tests = []
        try:
            model = VirgoClusterICMModel()
            tests.append({'name': 'Instantiation', 'passed': model is not None})
        except Exception as e:
            tests.append({'name': 'Instantiation', 'passed': False, 'error': str(e)})
        try:
            model = VirgoClusterICMModel()
            has_method = hasattr(model, 'compute') or hasattr(model, 'calculate') or hasattr(model, 'get_equation_text')
            tests.append({'name': 'Has compute method', 'passed': has_method})
        except Exception as e:
            tests.append({'name': 'Has compute method', 'passed': False, 'error': str(e)})
        all_passed = all(t['passed'] for t in tests)
        return {'class': 'VirgoClusterICMModel', 'tests': tests, 'passed': sum(1 for t in tests if t['passed']), 'total': len(tests), 'all_passed': all_passed}

