    def compute_M_merge(self, t: float) -> Tuple[float, str]:
        """
        Compute star formation-driven mass growth factor.
        
        M_merge(t) = SFR × t / M_initial
        
        Args:
            t: Time in seconds
            
        Returns:
            M_merge: Mass growth factor (dimensionless)
            steps: Calculation explanation
        """
        # Convert SFR to total mass formed
        t_years = t / 3.156e7
        mass_formed_solar = self.SFR * t_years  # M_☉
