    def validate_model(self) -> Tuple[bool, list, str]:
        """
        Run validation tests against document reference values.
        
        Returns:
            passed: True if all tests pass
            tests: List of test result strings
            summary: Summary string
        """
        import math
        
        tests = []
        passed_count = 0
        
        # Test 1: g_grav
        g_grav, _ = self.compute_g_grav()
        expected_g_grav = 5.902e-13
        ratio1 = g_grav / expected_g_grav
        pass1 = 0.99 <= ratio1 <= 1.01
        tests.append(f"Test 1: g_grav = {g_grav:.3e} / {expected_g_grav:.3e} = {ratio1:.4f} ∈ [0.99, 1.01]: {'PASS' if pass1 else 'FAIL'}")
        passed_count += int(pass1)
        
        # Test 2: H(z=3)
        H_z, _ = self.compute_H_z(z=3)
        expected_H_z = 1.011e-17
        ratio2 = H_z / expected_H_z
        pass2 = 0.95 <= ratio2 <= 1.05  # Wider tolerance for cosmological calculation
        tests.append(f"Test 2: H(z=3) = {H_z:.3e} / {expected_H_z:.3e} = {ratio2:.4f} ∈ [0.95, 1.05]: {'PASS' if pass2 else 'FAIL'}")
        passed_count += int(pass2)
        
        # Test 3: (1 + H(z)t)
        hubble_corr, _ = self.compute_hubble_correction(self.t_current)
        expected_hubble = 5.148
        ratio3 = hubble_corr / expected_hubble
        pass3 = 0.95 <= ratio3 <= 1.05
        tests.append(f"Test 3: (1+H(z)t) = {hubble_corr:.4f} / {expected_hubble:.4f} = {ratio3:.4f} ∈ [0.95, 1.05]: {'PASS' if pass3 else 'FAIL'}")
        passed_count += int(pass3)
        
        # Test 4: (1 + M_evo)
        M_evo_factor, _ = self.compute_M_evo(self.t_current)
        expected_M_evo = 1.13
        ratio4 = M_evo_factor / expected_M_evo
        pass4 = 0.99 <= ratio4 <= 1.01
        tests.append(f"Test 4: (1+M_evo) = {M_evo_factor:.4f} / {expected_M_evo:.4f} = {ratio4:.4f} ∈ [0.99, 1.01]: {'PASS' if pass4 else 'FAIL'}")
        passed_count += int(pass4)
        
        # Test 5: (1 - M_merge)
        merge_factor, _ = self.compute_M_merge(self.t_current)
        expected_merge = 0.8
        ratio5 = merge_factor / expected_merge
        pass5 = 0.99 <= ratio5 <= 1.01
        tests.append(f"Test 5: (1-M_merge) = {merge_factor:.4f} / {expected_merge:.4f} = {ratio5:.4f} ∈ [0.99, 1.01]: {'PASS' if pass5 else 'FAIL'}")
        passed_count += int(pass5)
        
        # Test 6: a_EM
        a_EM, _ = self.compute_electromagnetic_with_UA()
        expected_a_EM = 1.053e-3
        ratio6 = a_EM / expected_a_EM
        pass6 = 0.99 <= ratio6 <= 1.01
        tests.append(f"Test 6: a_EM = {a_EM:.4e} / {expected_a_EM:.4e} = {ratio6:.4f} ∈ [0.99, 1.01]: {'PASS' if pass6 else 'FAIL'}")
        passed_count += int(pass6)
        
        # Test 7: g_HUDF total
        g_total, _ = self.compute_clean_equation(self.t_current)
        expected_g_total = 1.053e-3
        ratio7 = g_total / expected_g_total
        pass7 = 0.99 <= ratio7 <= 1.01
        tests.append(f"Test 7: g_HUDF = {g_total:.4e} / {expected_g_total:.4e} = {ratio7:.4f} ∈ [0.99, 1.01]: {'PASS' if pass7 else 'FAIL'}")
        passed_count += int(pass7)
        
        # Test 8: EM dominance (>99% of total)
        EM_fraction = a_EM / g_total
        pass8 = EM_fraction > 0.99
        tests.append(f"Test 8: EM fraction = {EM_fraction:.6f} > 0.99: {'PASS' if pass8 else 'FAIL'}")
        passed_count += int(pass8)
        
        all_passed = passed_count == 8
        summary = f"HUDFModel: {passed_count}/8 tests passed"
        
        return all_passed, tests, summary
    
    # ═══════════════════════════════════════════════════════════════════════════
    # STATIC TEST RUNNER
    # ═══════════════════════════════════════════════════════════════════════════
    
    @staticmethod
    def run_tests() -> dict:
        """
        Run comprehensive tests on HUDFModel.
        
        Returns:
            dict: Test results with pass/fail status and details
        """
        tests = []
        
        # Test 1: Instantiation
        try:
            model = HUDFModel()
            tests.append({'name': 'Instantiation', 'passed': True, 'message': 'Model created successfully'})
        except Exception as e:
            tests.append({'name': 'Instantiation', 'passed': False, 'message': str(e)})
            return {'class': 'HUDFModel', 'tests': tests, 'passed': 0, 'total': 1, 'all_passed': False}
        
        # Test 2: compute_H_z
