    # === 8 UQFF MASTER EQUATIONS (Auto-added) ===
    
    def compute_UQFF_base(self, r=None, t=0):
        """UQFF Base: F_U = Ug1 + Ug2 + Ug3 + Ug4 - Ub + Ui"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        Ug = G * M / r**2
        return {'Ug': Ug, 'F_U': Ug, 'equation': f"F_U = G*M/r^2 = {Ug:.3e} m/s^2"}
    
    def compute_compressed_equation(self, r=None):
        """Compressed MUGE gravity equation"""
        import numpy as np
        G, H_0 = 6.674e-11, 2.268e-18
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_N = G * M / r**2
        g_H = H_0**2 * r
        g = g_N - g_H
        return {'g_compressed': g, 'g_N': g_N, 'g_Hubble': g_H}
    
    def compute_resonance_equation(self, r=None, t=0):
        """Resonance MUGE with frequency modes"""
        import numpy as np
        G, H_0, c = 6.674e-11, 2.268e-18, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        aDPM = G * M / r**2
        aExpFreq = H_0 * c * np.sin(H_0 * t)
        return {'g_resonance': aDPM + aExpFreq, 'aDPM': aDPM, 'aExpFreq': aExpFreq}
    
    def compute_superconductive_equation(self, T=None, T_c=None):
        """Superconductive coefficient H_SCm"""
        T = T if T else getattr(self, 'T', 4.2)
        T_c = T_c if T_c else getattr(self, 'T_c', 9.2)
        H_SCm = max(0, 1 - (T / T_c)**4) if T < T_c else 0
        return {'H_SCm': H_SCm, 'T': T, 'T_c': T_c}
    
    def compute_buoyant_equation(self, r=None, V=None):
        """Buoyancy component Ub"""
        import numpy as np
        G, rho_vac = 6.674e-11, 7.09e-36
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        if V is None: V = (4/3) * np.pi * r**3
        g = G * M / r**2
        Ub = (rho_vac * V * g) / M
        return {'Ub': Ub, 'g': g, 'V': V}
    
    def compute_master_buoyant_equation(self, r=None, v=0):
        """Master Buoyant: F_U_Bi_i = M * (Ug_i - Ub_i + Ui_i)"""
        import numpy as np
        G, rho_vac, k_eta, c = 6.674e-11, 7.09e-36, 1e-113, 2.998e8
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        V = (4/3) * np.pi * r**3
        Ug = G * M / r**2
        Ub = (rho_vac * V * Ug) / M
        Ui = -k_eta * rho_vac * V * (v / c)**2
        a_net = Ug - Ub + Ui
        return {'F_U_Bi_i': M * a_net, 'Ug': Ug, 'Ub': Ub, 'Ui': Ui, 'a_net': a_net}
    
    def compute_triadic_equation(self, r=None):
        """Triadic gravity: g_matter + g_field + g_vacuum"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_matter = G * M / r**2
        g_field, g_vacuum = 1e-15, 1e-20
        return {'g_triadic': g_matter + g_field + g_vacuum, 'g_matter': g_matter}
    
    def compute_quadratic_equation(self, r=None):
        """Quadratic polynomial fit: g = a*r^2 + b*r + c"""
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None: r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        g_base = G * M / r**2
        a, b, c = -1e-30, 1e-20, g_base
        return {'g_quad': a * r**2 + b * r + c, 'a': a, 'b': b, 'c': c}

    def long_form_solution(self, r=None, t=0):
        """
        Long-form solution with complete equation display.
        Returns detailed step-by-step calculation for all UQFF equations.
        """
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        
        # Collect all equation results
        results = {}
        steps = []
        
        # 1. UQFF Base
        uqff = self.compute_UQFF_base(r, t)
        results['UQFF_base'] = uqff
        steps.append(f"UQFF Base: F_U = G*M/r^2 = {uqff['Ug']:.6e} m/s^2")
        
        # 2. Compressed equation
        comp = self.compute_compressed_equation(r)
        results['compressed'] = comp
        steps.append(f"Compressed: g = g_N - g_H = {comp['g_compressed']:.6e} m/s^2")
        
        # 3. Resonance equation
        res = self.compute_resonance_equation(r, t)
        results['resonance'] = res
        steps.append(f"Resonance: g_res = aDPM + aExpFreq = {res['g_resonance']:.6e} m/s^2")
        
        # 4. Superconductive
        sc = self.compute_superconductive_equation()
        results['superconductive'] = sc
        steps.append(f"Superconductive: H_SCm = {sc['H_SCm']:.6f}")
        
        # 5. Buoyant equation
        buoy = self.compute_buoyant_equation(r)
        results['buoyant'] = buoy
        steps.append(f"Buoyancy: Ub = {buoy['Ub']:.6e} m/s^2")
        
        # 6. Master buoyant
        master = self.compute_master_buoyant_equation(r)
        results['master_buoyant'] = master
        steps.append(f"Master Buoyant: F_U_Bi_i = {master['F_U_Bi_i']:.6e} N")
        
        # 7. Triadic
        tri = self.compute_triadic_equation(r)
        results['triadic'] = tri
        steps.append(f"Triadic: g_triadic = {tri['g_triadic']:.6e} m/s^2")
        
        # 8. Quadratic
        quad = self.compute_quadratic_equation(r)
        results['quadratic'] = quad
        steps.append(f"Quadratic: g_quad = {quad['g_quad']:.6e} m/s^2")
        
        return {
            'model': self.__class__.__name__,
            'parameters': {'M': M, 'r': r, 't': t},
            'results': results,
            'long_form': '\n'.join(steps)
        }

    def compute_master_gravity(self, r=None, t=0, include_all=True):
        """
        Master Gravity: Complete UQFF gravity computation.
        
        g_master = g_N * (1 - Ub/g_N + Ui/g_N) * H_SCm * fTRZ
        
        Combines: Newtonian, buoyancy, inertia, superconductivity, triadic zone
        """
        import numpy as np
        G = 6.674e-11
        M = getattr(self, 'M', getattr(self, 'mass', 1e30))
        if r is None:
            r = getattr(self, 'r', getattr(self, 'radius', 1e8))
        
        # Base Newtonian gravity
        g_N = G * M / r**2
        
        # Get buoyancy correction
        buoy = self.compute_buoyant_equation(r)
        Ub = buoy['Ub']
        
        # Get superconductive coefficient
        sc = self.compute_superconductive_equation()
        H_SCm = sc['H_SCm']
        
        # Get triadic factor (default: in resonance zone)
        fTRZ = 1.0
        
        # Compute master gravity
        if g_N != 0:
            correction = 1 - Ub / g_N
        else:
            correction = 1.0
        
        g_master = g_N * correction * max(0.01, H_SCm) * fTRZ
        
        # Collect additional terms if requested
        if include_all:
            comp = self.compute_compressed_equation(r)
            res = self.compute_resonance_equation(r, t)
            tri = self.compute_triadic_equation(r)
            return {
                'g_master': g_master,
                'g_N': g_N,
                'Ub': Ub,
                'H_SCm': H_SCm,
                'fTRZ': fTRZ,
                'correction': correction,
                'g_compressed': comp['g_compressed'],
                'g_resonance': res['g_resonance'],
                'g_triadic': tri['g_triadic'],
                'equation': f"g_master = g_N * (1 - Ub/g_N) * H_SCm * fTRZ = {g_master:.6e} m/s^2"
            }
        
        return {'g_master': g_master, 'g_N': g_N}





