    def compute_H_z(self, z=None):
        """
        Compute Hubble parameter at redshift z.
        
        H(z) = H_0 × √(Ω_m(1+z)³ + Ω_Λ)
        
        Note: At Solar System scale (z ≈ 0), H(z) ≈ H_0.
        
        Args:
            z: Redshift (uses instance z = 0 if not specified)
            
        Returns:
            H(z) in s⁻¹
        """
        import math
        if z is None:
            z = self.z
        term = self.Omega_m * (1 + z)**3 + self.Omega_Lambda
        return self.H_0 * math.sqrt(term)
    
    def compute_hubble_correction(self, t=None, z=None):
        """
        Compute Hubble expansion correction factor.
        
        (1 + H(z)·t)
        
        At Solar System age (4.5 Gyr): ≈ 1.32
        
        Args:
            t: Time in seconds (uses instance t_age if not specified)
            z: Redshift (uses instance z if not specified)
            
        Returns:
            Hubble correction factor (dimensionless)
        """
        if t is None:
            t = self.t_age
        H_z = self.compute_H_z(z)
        return 1.0 + H_z * t
    
    def compute_g_sun(self, r_orbit=None):
        """
        Compute gravitational acceleration from the Sun at Saturn's orbit.
        
        g_sun = (G × M_Sun) / r_orbit²
        
        This is the acceleration keeping Saturn in orbit around the Sun.
        
        Args:
            r_orbit: Orbital distance in m (uses instance r_orbit if not specified)
            
        Returns:
            g_sun in m/s²
        """
        if r_orbit is None:
            r_orbit = self.r_orbit
        return (self.G * self.M_Sun) / (r_orbit**2)
    
    def compute_g_saturn(self, r=None, M=None):
        """
        Compute Saturn's surface gravitational acceleration.
        
        g_saturn = (G × M) / r²
        
        This is what you would feel standing on Saturn's cloud tops.
        
        Args:
            r: Radius in m (uses instance r_eq if not specified)
            M: Saturn mass in kg (uses instance M if not specified)
            
        Returns:
            g_saturn in m/s²
        """
        if r is None:
            r = self.r_eq
        if M is None:
            M = self.M
        return (self.G * M) / (r**2)
    
    def compute_T_ring(self, M_ring=None, r_ring=None):
        """
        Compute ring system tidal acceleration.
        
        T_ring = (G × M_ring) / r_ring²
        
        The rings create a small tidal influence on nearby material
        (atmosphere, moons, ring particles themselves).
        
        Args:
            M_ring: Ring mass in kg (uses instance M_ring if not specified)
            r_ring: Ring radius in m (uses instance r_ring if not specified)
            
        Returns:
            T_ring in m/s²
        """
        if M_ring is None:
            M_ring = self.M_ring
        if r_ring is None:
            r_ring = self.r_ring
        return (self.G * M_ring) / (r_ring**2)
    
    def compute_a_wind(self, rho_atm=None, v_wind=None):
        """
        Compute atmospheric wind feedback acceleration.
        
        a_wind = ρ_atm × v_wind² × scale
        
        Saturn's powerful winds (up to 1,800 km/h) create dynamic pressure
        effects on atmospheric circulation. The scaling converts pressure
        to effective acceleration.
        
        Document derivation:
            F_wind = ρ × v² = 2e-4 × (500)² = 50 N/m²
            a = F / ρ = 50 / 2e-4 = 2.5e5 m/s²
            Scaled: 2.5e5 × 10^-12 = 2.5e-7 m/s²
        
        Args:
            rho_atm: Atmospheric density in kg/m³
            v_wind: Wind speed in m/s
            
        Returns:
            a_wind in m/s²
        """
        if rho_atm is None:
            rho_atm = self.rho_atm
        if v_wind is None:
            v_wind = self.v_wind
        
        # Dynamic pressure
        F_wind = rho_atm * v_wind**2  # N/m²
        
        # Convert to acceleration
        a = F_wind / rho_atm  # m/s²
        
        # Scale for macroscopic effects
        macro_scale = 1e-12
        return a * macro_scale
    
    def compute_a_EM_with_UA(self, v=None, B=None):
        """
        Compute electromagnetic acceleration with UA correction.
        
        a_EM = q(v×B)(1 + ρ_UA/ρ_SCm) × macro_scale
        
        This term models magnetic effects on charged particles in the
        atmosphere and ring system, enhanced by Aether [UA] correction.
        
        Document derivation:
            q(v×B) = 1.602e-19 × 500 × 10^-7 = 8.01e-23 N
            a = F/m = 8.01e-23 / 1.673e-27 = 4.789e4 m/s²
            UA correction = 1 + (7.09e-36 / 7.09e-37) = 11
            Raw a_EM = 4.789e4 × 11 = 5.268e5 m/s²
            Scaled a_EM = 5.268e5 × 10^-12 = 5.268e-7 m/s²
        
        Args:
            v: Velocity in m/s (uses instance v_wind if not specified)
            B: Magnetic field in T (uses instance B if not specified)
            
        Returns:
            a_EM in m/s²
        """
        if v is None:
            v = self.v_wind
        if B is None:
            B = self.B
        
        # Lorentz force on proton: F = q(v×B)
        F_lorentz = self.q_proton * v * B
        
        # Acceleration on proton: a = F/m
        a_raw = F_lorentz / self.m_proton
        
        # UA correction factor
        UA_factor = 1.0 + (self.rho_vac_UA / self.rho_vac_SCm)  # = 11
        
        # Apply UA correction
        a_corrected = a_raw * UA_factor
        
        # Macroscopic scaling for planetary-scale effects
        macro_scale = 1e-12
        
        return a_corrected * macro_scale
    
    def compute_clean_equation(self, t=None):
        """
        Compute the clean UQFF master equation for Saturn's gravitational evolution.
        
        g_Saturn(r, t) = g_sun × (1 + H(z)·t) × (1 + f_TRZ) + g_saturn + T_ring + a_wind + a_EM
        
        This equation combines:
        - Solar gravitational acceleration at Saturn's orbit
        - Saturn's own surface gravity (dominant term)
        - Ring system tidal effects
        - Atmospheric wind feedback
        - Electromagnetic effects with UA correction
        
        Args:
            t: Time in seconds (uses instance t_age if not specified)
            
        Returns:
            dict with all computed values and final g_Saturn
        """
        if t is None:
            t = self.t_age
        
        # Solar gravitational acceleration at orbit
        g_sun = self.compute_g_sun()
        
        # Hubble expansion correction
        hubble_factor = self.compute_hubble_correction(t)
        
        # Time-reversal zone correction
        trz_factor = 1.0 + self.f_TRZ
        
        # Solar term with corrections (orbital dynamics)
        g_sun_corrected = g_sun * hubble_factor * trz_factor
        
        # Saturn's surface gravity (local, dominant)
        g_saturn = self.compute_g_saturn()
        
        # Ring system tidal acceleration
        T_ring = self.compute_T_ring()
        
        # Atmospheric wind feedback
        a_wind = self.compute_a_wind()
        
        # Electromagnetic with UA correction
        a_EM = self.compute_a_EM_with_UA()
        
        # Final clean equation
        g_Saturn = g_sun_corrected + g_saturn + T_ring + a_wind + a_EM
        
        # Breakdown percentages
        total = g_Saturn
        
        return {
            'g_sun': g_sun,
            'hubble_factor': hubble_factor,
            'trz_factor': trz_factor,
            'g_sun_corrected': g_sun_corrected,
            'g_saturn': g_saturn,
            'T_ring': T_ring,
            'a_wind': a_wind,
            'a_EM': a_EM,
            'g_Saturn': g_Saturn,
            'breakdown': {
                'g_sun_pct': 100 * g_sun_corrected / total if total > 0 else 0,
                'g_saturn_pct': 100 * g_saturn / total if total > 0 else 0,
                'T_ring_pct': 100 * T_ring / total if total > 0 else 0,
                'a_wind_pct': 100 * a_wind / total if total > 0 else 0,
                'a_EM_pct': 100 * a_EM / total if total > 0 else 0
            }
        }
    
    def compute_ring_properties(self):
        """
        Compute comprehensive ring system properties.
        
        Saturn's iconic ring system is primarily water ice with trace dust,
        with an estimated lifetime of ~100 million years.
        
        Returns:
            dict with ring physical properties
        """
        import math
        
        # Ring mass loss at current rate
        years_to_depletion = self.M_ring / (self.ring_loss_rate * 3.156e7)
        
        # Ring optical properties (simplified)
        ring_width = CONSTANTS.get('Saturn_r_ring_outer', 1.4e8) - self.r_ring
        ring_area = math.pi * (CONSTANTS.get('Saturn_r_ring_outer', 1.4e8)**2 - self.r_ring**2)
        
        # Average ring surface density
        surface_density = self.M_ring / ring_area
        
        # Roche limit (where tidal forces prevent moon formation)
        roche_limit = self.r_eq * (2 * self.M / self.M_ring)**(1/3)
        
        # Orbital velocity at ring location
        v_ring_orbit = (self.G * self.M / self.r_ring)**0.5
        
        return {
            'M_ring_kg': self.M_ring,
            'M_ring_ratio': self.M_ring / self.M,
            'r_ring_avg': self.r_ring,
            'r_ring_outer': CONSTANTS.get('Saturn_r_ring_outer', 1.4e8),
            'ring_width': ring_width,
            'ring_area': ring_area,
            'surface_density': surface_density,
            'loss_rate_kg_s': self.ring_loss_rate,
            'lifetime_years': years_to_depletion,
            'lifetime_Myr': years_to_depletion / 1e6,
            'roche_limit': roche_limit,
            'v_ring_orbit': v_ring_orbit
        }
    
    def compute_atmospheric_properties(self):
        """
        Compute comprehensive atmospheric properties.
        
        Saturn's atmosphere features banded clouds and seasonal storms,
        including the dramatic Great White Spots.
        
        Returns:
            dict with atmospheric properties
        """
        import math
        
        # Sound speed (isothermal approximation, T ~ 134 K at cloud tops)
        T_cloud = 134  # K
        k_B = 1.381e-23  # J/K
        m_H2 = 3.347e-27  # kg (H2 molecule)
        mu = 2.3  # Mean molecular weight
        c_s = math.sqrt(k_B * T_cloud / (mu * m_H2))
        
        # Mach number of winds
        mach = self.v_wind / c_s
        
        # Scale height
        scale_height = (k_B * T_cloud) / (mu * m_H2 * self.compute_g_saturn())
        
        # Rotational velocity at equator
        v_rotation = 2 * math.pi * self.r_eq / self.rotation_period
        
        # Rossby number (wind vs rotation)
        rossby = self.v_wind / (2 * math.pi * self.r_eq / self.rotation_period)
        
        return {
            'rho_atm': self.rho_atm,
            'v_wind': self.v_wind,
            'v_wind_max_km_h': CONSTANTS.get('Saturn_v_wind_max', 1800),
            'T_cloud_top': T_cloud,
            'c_sound': c_s,
            'mach_number': mach,
            'scale_height': scale_height,
            'rotation_period': self.rotation_period,
            'v_rotation': v_rotation,
            'rossby_number': rossby
        }
    
    def compute_orbital_properties(self):
        """
        Compute Saturn's orbital properties around the Sun.
        
        Returns:
            dict with orbital properties
        """
        import math
        
        # Orbital velocity
        v_orbit = 2 * math.pi * self.r_orbit / self.orbit_period
        
        # Escape velocity at orbital distance from Sun
        v_escape_sun = math.sqrt(2 * self.G * self.M_Sun / self.r_orbit)
        
        # Hill sphere radius (Saturn's gravitational influence zone)
        r_hill = self.r_orbit * (self.M / (3 * self.M_Sun))**(1/3)
        
        # Orbital energy per unit mass
        E_orbit = -self.G * self.M_Sun / (2 * self.r_orbit)
        
        return {
            'r_orbit_m': self.r_orbit,
            'r_orbit_AU': self.r_orbit / 1.496e11,
            'orbit_period_s': self.orbit_period,
            'orbit_period_yr': self.orbit_period / 3.156e7,
            'v_orbit': v_orbit,
            'v_escape_sun': v_escape_sun,
            'r_hill': r_hill,
            'r_hill_AU': r_hill / 1.496e11,
            'E_orbit_specific': E_orbit,
            'g_sun': self.compute_g_sun()
        }
    
    def validate_model(self):
        """
        Validate model outputs against document reference values.
        
        Returns:
            dict with validation results and pass/fail status
        """
        results = self.compute_clean_equation()
        
        # Compare to document values
        g_sun_ratio = results['g_sun'] / self.g_sun_doc if self.g_sun_doc != 0 else float('inf')
        g_saturn_ratio = results['g_saturn'] / self.g_saturn_doc if self.g_saturn_doc != 0 else float('inf')
        T_ring_ratio = results['T_ring'] / self.T_ring_doc if self.T_ring_doc != 0 else float('inf')
        a_wind_ratio = results['a_wind'] / self.a_wind_doc if self.a_wind_doc != 0 else float('inf')
        g_total_ratio = results['g_Saturn'] / self.g_total_doc if self.g_total_doc != 0 else float('inf')
        
        # Tolerance bounds (±1%)
        tol_low, tol_high = 0.99, 1.01
        
        validations = {
            'g_sun': {
                'computed': results['g_sun'],
                'document': self.g_sun_doc,
                'ratio': g_sun_ratio,
                'passed': tol_low <= g_sun_ratio <= tol_high
            },
            'g_saturn': {
                'computed': results['g_saturn'],
                'document': self.g_saturn_doc,
                'ratio': g_saturn_ratio,
                'passed': tol_low <= g_saturn_ratio <= tol_high
            },
            'T_ring': {
                'computed': results['T_ring'],
                'document': self.T_ring_doc,
                'ratio': T_ring_ratio,
                'passed': tol_low <= T_ring_ratio <= tol_high
            },
            'a_wind': {
                'computed': results['a_wind'],
                'document': self.a_wind_doc,
                'ratio': a_wind_ratio,
                'passed': tol_low <= a_wind_ratio <= tol_high
            },
            'g_Saturn': {
                'computed': results['g_Saturn'],
                'document': self.g_total_doc,
                'ratio': g_total_ratio,
                'passed': tol_low <= g_total_ratio <= tol_high
            }
        }
        
        all_passed = all(v['passed'] for v in validations.values())
        
        return {
            'validations': validations,
            'all_passed': all_passed,
            'computed_results': results
        }
    
